import {useMemo} from 'react';
import * as THREE from 'three';
import {watchMaterials as M} from '../materials/watchMaterials';
import {makeRoundedRect, makeScrewHead} from '../geometry/watchGeometry';

const batteryGeometry = makeRoundedRect(1.45, 2.45, 0.20, 0.16);
const pcbGeometry = makeRoundedRect(3.65, 3.65, 0.075, 0.30);
const screwGeometry = makeScrewHead();

const RearMarkings = () => {
  const texture = useMemo(() => {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 88;
    const ctx = canvas.getContext('2d');
    if (!ctx) return new THREE.CanvasTexture(canvas);
    ctx.fillStyle = '#0d1318';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#8b9ca4';
    ctx.font = '26px Arial, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('CHRONOS X   |   CX-46   |   HR SENSOR', 256, 50);
    const map = new THREE.CanvasTexture(canvas);
    map.colorSpace = THREE.SRGBColorSpace;
    return map;
  }, []);
  return <mesh name="rear-manufacturing-marking" position={[0, -1.36, -0.03]} rotation={[0, 0, Math.PI]}>
    <planeGeometry args={[1.10, 0.19]} />
    <meshBasicMaterial map={texture} transparent opacity={0.75} side={THREE.DoubleSide} />
  </mesh>;
};

