import React, {useMemo} from 'react';
import {Environment, Lightformer} from '@react-three/drei';
import * as THREE from 'three';
import {Reflector} from 'three/examples/jsm/objects/Reflector.js';

export type LightingPreset =
  | 'awakening'
  | 'reveal'
  | 'engineering'
  | 'elevation'
  | 'macro-grille'
  | 'macro-touch'
  | 'macro-contacts'
  | 'hero'
  | 'brand';

interface StudioLightingProps {
  preset: LightingPreset;
  highlightSweep?: number; // 0 to 1 for moving lights
  showFloor?: boolean;
}

export const StudioLighting: React.FC<StudioLightingProps> = ({
  preset,
  highlightSweep = 0,
  showFloor = true,
}) => {
  const floor = useMemo(() => {
    const r = new Reflector(new THREE.PlaneGeometry(60, 60), {
      textureWidth: 1536,
      textureHeight: 1536,
      color: 0x88a2b0,
      clipBias: 0.003,
    });
    r.position.y = 0.0;
    r.rotation.x = -Math.PI / 2;
    const mat = r.material as THREE.ShaderMaterial;
    mat.fragmentShader = mat.fragmentShader.replace(
      'gl_FragColor = vec4( blendOverlay( base.rgb, color ), 1.0 );',
      'gl_FragColor = vec4( base.rgb * 0.68, 1.0 );'
    );
    return r;
  }, []);

  const particles = useMemo(() => {
    const p: number[] = [];
    const count = 48;
    for (let i = 0; i < count; i++) {
      const x = ((i * 37 + 13) % 100) / 12 - 4.2;
      const y = ((i * 53 + 7) % 100) / 16 + 1.2;
      const z = ((i * 71 + 29) % 100) / 25 - 2.0;
      p.push(x, y, z);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
    return geo;
  }, []);

  return (
    <>
      {preset === 'awakening' && (
        <>
          <ambientLight intensity={0.015} color="#456677" />
          {/* Moving narrow slit light tracking across the metallic edge */}
          <spotLight
            position={[-4.0 + highlightSweep * 8.0, 3.5, 4.0]}
            target-position={[0, 1.8, 0]}
            intensity={45}
            angle={0.28}
            penumbra={0.7}
            color="#e6f6ff"
          />
          <pointLight
            position={[1.5, 1.2, 2.5]}
            intensity={6 + highlightSweep * 10}
            color="#4acaff"
            decay={2}
          />
        </>
      )}

      {preset === 'reveal' && (
        <>
          <ambientLight intensity={0.08} color="#7ba5b8" />
          <directionalLight position={[-4, 7, 5]} intensity={4.2} color="#dcf2ff" />
          <pointLight position={[5, 4, -2]} intensity={75} color="#52c8ff" decay={2} />
          <pointLight position={[-4, 2, 2]} intensity={35} color="#85d8ff" decay={2} />
          <rectAreaLight
            position={[0, 4.5, 5]}
            rotation={[-0.4, 0, 0]}
            intensity={3.2}
            width={6}
            height={3}
            color="#cce6f5"
          />
        </>
      )}

      {preset === 'engineering' && (
        <>
          <ambientLight intensity={0.16} color="#8db8cc" />
          {/* Direct key illumination from camera-side onto hinge & lid seam */}
          <directionalLight position={[2.5, 5.5, 4.5]} intensity={6.0} color="#eef8ff" />
          <pointLight position={[-2.5, 3.5, 3.5]} intensity={70} color="#6cd4ff" decay={2} />
          <pointLight position={[0, 2.2, 3.2]} intensity={50} color="#90e0ff" decay={2} />
        </>
      )}

      {preset === 'elevation' && (
        <>
          <ambientLight intensity={0.06} color="#5f8fa5" />
          {/* Dramatic upward backlighting as earbuds rise */}
          <spotLight
            position={[0, 0.4, -2.5]}
            target-position={[0, 4.0, 0]}
            intensity={85}
            angle={0.65}
            penumbra={0.8}
            color="#68d8ff"
          />
          <directionalLight position={[-4, 8, 4]} intensity={3.8} color="#e0f4ff" />
          <pointLight position={[4, 5, 1]} intensity={55} color="#7fe0ff" decay={2} />
        </>
      )}

      {preset === 'macro-grille' && (
        <>
          <ambientLight intensity={0.18} color="#98c6dc" />
          {/* Camera-side directional light directly on the nozzle & silicone tip */}
          <directionalLight position={[1.5, 3.5, 4.5]} intensity={7.0} color="#f4fbff" />
          <pointLight position={[-2.0, 2.5, 3.0]} intensity={65} color="#65d4ff" decay={2} />
          <pointLight position={[0, 1.2, 2.5]} intensity={45} color="#ffffff" decay={2} />
        </>
      )}

      {preset === 'macro-touch' && (
        <>
          <ambientLight intensity={0.03} color="#6b93a8" />
          {/* Specular highlight sweep across the glossy touch facet */}
          <directionalLight
            position={[-2.5 + highlightSweep * 4.0, 7.5, 3.5]}
            intensity={5.5}
            color="#f2f9ff"
          />
          <pointLight position={[2.5, 4.5, 0.5]} intensity={65} color="#55d0ff" decay={2} />
        </>
      )}

      {preset === 'macro-contacts' && (
        <>
          <ambientLight intensity={0.08} color="#85aebb" />
          {/* Direct downlight into the charging contacts */}
          <spotLight
            position={[-0.89, 4.8, 0.5]}
            target-position={[-0.89, 1.5, 0.1]}
            intensity={85}
            angle={0.4}
            penumbra={0.4}
            color="#fff6e0"
          />
          <pointLight position={[-0.89, 2.5, 0.8]} intensity={45} color="#62d8ff" decay={2} />
        </>
      )}

      {(preset === 'hero' || preset === 'brand') && (
        <>
          <ambientLight intensity={0.08} color="#8cb2c6" />
          <directionalLight position={[-5.5, 8.5, 5]} intensity={4.5} color="#e4f4ff" />
          <pointLight position={[4.6, 3.6, -0.6]} intensity={75} color="#62d2ff" decay={2} />
          <pointLight position={[-4.5, 3.2, 0.5]} intensity={38} color="#8edbff" decay={2} />
          <rectAreaLight
            position={[0, 5.2, 4.2]}
            rotation={[-0.45, 0, 0]}
            intensity={3.5}
            width={6}
            height={3.5}
            color="#d0e5f2"
          />
        </>
      )}

      {/* Studio HDRI reflection environment */}
      <Environment resolution={256} frames={1}>
        <Lightformer
          position={[-4.5, 5, 2.5]}
          rotation={[0, Math.PI / 3, 0]}
          scale={[2.5, 8, 1]}
          intensity={preset === 'awakening' ? 1.5 : 6.5}
          color="#dcf4ff"
        />
        <Lightformer
          position={[4.5, 3.5, 0]}
          rotation={[0, -Math.PI / 2, 0]}
          scale={[1.5, 7, 1]}
          intensity={preset === 'awakening' ? 2.0 : 8.5}
          color="#82ddff"
        />
        <Lightformer
          position={[0, 6.5, 0]}
          rotation={[Math.PI / 2, 0, 0]}
          scale={[7, 2.5, 1]}
          intensity={3.2}
          color="#ffffff"
        />
      </Environment>

      {/* Calibrated Studio Backdrop */}
      <mesh position={[0, 7.5, -7]}>
        <planeGeometry args={[45, 20]} />
        <shaderMaterial
          uniforms={{}}
          vertexShader={`
            varying vec2 vUv;
            void main() {
              vUv = uv;
              gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
          `}
          fragmentShader={`
            varying vec2 vUv;
            void main() {
              vec2 p = vec2((vUv.x - 0.46) * 3.5, (vUv.y - 0.32) * 2.2);
              float halo = exp(-dot(p, p) * 6.5);
              vec3 darkBase = vec3(0.003, 0.007, 0.010);
              vec3 haloColor = vec3(0.052, 0.100, 0.138);
              vec3 c = mix(darkBase, haloColor, halo);
              gl_FragColor = vec4(c, 1.0);
              #include <tonemapping_fragment>
              #include <colorspace_fragment>
            }
          `}
        />
      </mesh>

      {/* Atmospheric dust particles */}
      <points geometry={particles}>
        <pointsMaterial
          size={0.032}
          color="#92cadc"
          transparent
          opacity={0.30}
          sizeAttenuation
        />
      </points>

      {showFloor && <primitive object={floor} />}
    </>
  );
};
