import React, {useLayoutEffect} from 'react';
import {useThree} from '@react-three/fiber';
import * as THREE from 'three';

export interface CinematicCameraProps {
  position: [number, number, number];
  target: [number, number, number];
  fov?: number;
}

export const CinematicCamera: React.FC<CinematicCameraProps> = ({
  position,
  target,
  fov = 36.5,
}) => {
  const {camera} = useThree();

  useLayoutEffect(() => {
    camera.position.set(position[0], position[1], position[2]);
    camera.lookAt(target[0], target[1], target[2]);

    const persCamera = camera as THREE.PerspectiveCamera;
    if (persCamera.isPerspectiveCamera) {
      if (persCamera.fov !== fov) {
        persCamera.fov = fov;
      }
      persCamera.updateProjectionMatrix();
    }
  }, [camera, position[0], position[1], position[2], target[0], target[1], target[2], fov]);

  return null;
};
