import {interpolate, spring, Easing} from 'remotion';
import {SHOTS} from './shotTimeline';

export type StudioPreset =
  | 'awakening'
  | 'reveal'
  | 'engineering'
  | 'elevation'
  | 'macro-grille'
  | 'macro-touch'
  | 'macro-contacts'
  | 'hero'
  | 'brand';

export interface ShotState {
  shotIndex: number;
  shotName: string;
  localFrame: number;
  camera: {
    position: [number, number, number];
    target: [number, number, number];
    fov: number;
  };
  lighting: {
    preset: StudioPreset;
    highlightSweep?: number;
    showFloor: boolean;
  };
  caseProps: {
    visible: boolean;
    position: [number, number, number];
    rotation: [number, number, number];
    scale: number;
    opening: number;
  };
  leftEarbudProps: {
    visible: boolean;
    parent: 'world' | 'case';
    position: [number, number, number];
    rotation: [number, number, number];
    scale: number;
  };
  rightEarbudProps: {
    visible: boolean;
    parent: 'world' | 'case';
    position: [number, number, number];
    rotation: [number, number, number];
    scale: number;
  };
  macroEarbudProps?: {
    visible: boolean;
    side: number;
    position: [number, number, number];
    rotation: [number, number, number];
    scale: number;
    innerGroupPosition?: [number, number, number];
  };
  overlay: {
    textOpacity: number;
    sceneOpacity: number;
    background: string;
  };
}

export function getShotState(frame: number, fps = 30): ShotState {
  // Clamp frame to [0, 749]
  const f = Math.max(0, Math.min(749, frame));

  // SHOT 01: THE AWAKENING (Frames 0 - 89)
  if (f <= SHOTS.SHOT_01_AWAKENING.to) {
    const local = f - SHOTS.SHOT_01_AWAKENING.from;
    const progress = interpolate(local, [0, 89], [0, 1], {
      easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });

    const camX = interpolate(progress, [0, 1], [0.8, 1.4]);
    const camY = interpolate(progress, [0, 1], [2.6, 2.2]);
    const camZ = interpolate(progress, [0, 1], [4.2, 2.4]);
    const targetX = interpolate(progress, [0, 1], [0.5, 0.9]);
    const targetY = interpolate(progress, [0, 1], [2.2, 1.9]);
    const targetZ = interpolate(progress, [0, 1], [0.8, 0.4]);

    const highlightSweep = interpolate(local, [10, 80], [0, 1], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });

    return {
      shotIndex: 1,
      shotName: 'Shot 01: The Awakening',
      localFrame: local,
      camera: {
        position: [camX, camY, camZ],
        target: [targetX, targetY, targetZ],
        fov: 24,
      },
      lighting: {
        preset: 'awakening',
        highlightSweep,
        showFloor: false,
      },
      caseProps: {
        visible: true,
        position: [0, 1.8, 0],
        rotation: [0.08, -0.28, 0.15],
        scale: 1.0,
        opening: 0.0,
      },
      leftEarbudProps: {
        visible: false,
        parent: 'case',
        position: [-0.89, 0.4, 0],
        rotation: [-0.2, 0, 0],
        scale: 0.88,
      },
      rightEarbudProps: {
        visible: false,
        parent: 'case',
        position: [0.89, 0.4, 0],
        rotation: [-0.2, 0, 0],
        scale: 0.88,
      },
      overlay: {
        textOpacity: 0,
        sceneOpacity: 1,
        background: '#050a0e',
      },
    };
  }

  // SHOT 02: THE REVEAL (Frames 90 - 209)
  if (f <= SHOTS.SHOT_02_REVEAL.to) {
    const local = f - SHOTS.SHOT_02_REVEAL.from;
    const progress = interpolate(local, [0, 119], [0, 1], {
      easing: Easing.bezier(0.42, 0.0, 0.58, 1.0),
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });

    const radius = 14.8;
    const startAngle = -Math.PI / 4;
    const endAngle = startAngle + (2 * Math.PI) / 3;
    const currentAngle = interpolate(progress, [0, 1], [startAngle, endAngle]);

    const camX = Math.sin(currentAngle) * radius;
    const camY = interpolate(progress, [0, 1], [4.2, 3.4]);
    const camZ = Math.cos(currentAngle) * radius;
    const caseY = 1.45 + Math.sin(progress * Math.PI) * 0.08;

    return {
      shotIndex: 2,
      shotName: 'Shot 02: The Reveal',
      localFrame: local,
      camera: {
        position: [camX, camY, camZ],
        target: [0, 1.45, 0],
        fov: 34,
      },
      lighting: {
        preset: 'reveal',
        showFloor: true,
      },
      caseProps: {
        visible: true,
        position: [0, caseY, 0],
        rotation: [0.04, -0.1, 0.12],
        scale: 1.0,
        opening: 0.0,
      },
      leftEarbudProps: {
        visible: false,
        parent: 'case',
        position: [-0.89, 0.4, 0],
        rotation: [-0.2, 0, 0],
        scale: 0.88,
      },
      rightEarbudProps: {
        visible: false,
        parent: 'case',
        position: [0.89, 0.4, 0],
        rotation: [-0.2, 0, 0],
        scale: 0.88,
      },
      overlay: {
        textOpacity: 0,
        sceneOpacity: 1,
        background: '#070f14',
      },
    };
  }

  // SHOT 03: PRECISION ENGINEERING (Frames 210 - 329)
  if (f <= SHOTS.SHOT_03_LID_OPENING.to) {
    const local = f - SHOTS.SHOT_03_LID_OPENING.from;
    const openProgress = spring({
      frame: local - 15,
      fps,
      config: {damping: 14, stiffness: 65, mass: 1.2},
    });

    const opening = interpolate(openProgress, [0, 1], [0.0, 1.68], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });

    const camProgress = interpolate(local, [0, 119], [0, 1], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });

    const camX = interpolate(camProgress, [0, 1], [2.8, 2.2]);
    const camY = interpolate(camProgress, [0, 1], [4.2, 3.8]);
    const camZ = interpolate(camProgress, [0, 1], [14.0, 13.2]);
    const targetY = interpolate(camProgress, [0, 1], [1.6, 1.8]);

    return {
      shotIndex: 3,
      shotName: 'Shot 03: Precision Engineering',
      localFrame: local,
      camera: {
        position: [camX, camY, camZ],
        target: [0, targetY, 0],
        fov: 32,
      },
      lighting: {
        preset: 'engineering',
        showFloor: false,
      },
      caseProps: {
        visible: true,
        position: [0, 1.4, 0],
        rotation: [0.12, 2.5, -0.05],
        scale: 1.0,
        opening,
      },
      leftEarbudProps: {
        visible: true,
        parent: 'case',
        position: [-0.89, 0.4, 0],
        rotation: [-0.2, 0, 0],
        scale: 0.88,
      },
      rightEarbudProps: {
        visible: true,
        parent: 'case',
        position: [0.89, 0.4, 0],
        rotation: [-0.2, 0, 0],
        scale: 0.88,
      },
      overlay: {
        textOpacity: 0,
        sceneOpacity: 1,
        background: '#070f14',
      },
    };
  }

  // SHOT 04: THE ELEVATION (Frames 330 - 449)
  if (f <= SHOTS.SHOT_04_ELEVATION.to) {
    const local = f - SHOTS.SHOT_04_ELEVATION.from;
    const riseSpring = spring({
      frame: local - 10,
      fps,
      config: {damping: 14, stiffness: 40, mass: 1.1},
    });

    const t = interpolate(riseSpring, [0, 1], [0, 1], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });

    const leftX = interpolate(t, [0, 0.4, 1], [-0.89, -1.05, -1.28]);
    const leftY = interpolate(t, [0, 0.5, 1], [0.4, 1.9, 3.4]);
    const leftZ = interpolate(t, [0, 1], [0.0, 0.05]);
    const leftRotX = interpolate(t, [0, 1], [-0.2, 0.52]);
    const leftRotY = interpolate(t, [0, 1], [0.0, -0.18]);
    const leftRotZ = interpolate(t, [0, 1], [0.0, -0.46]);
    const leftScale = interpolate(t, [0, 1], [0.88, 1.15]);

    const rightX = interpolate(t, [0, 0.4, 1], [0.89, 0.92, 0.94]);
    const rightY = interpolate(t, [0, 0.5, 1], [0.4, 1.7, 3.0]);
    const rightZ = interpolate(t, [0, 1], [0.0, 0.08]);
    const rightRotX = interpolate(t, [0, 1], [-0.2, 0.55]);
    const rightRotY = interpolate(t, [0, 1], [0.0, 0.3]);
    const rightRotZ = interpolate(t, [0, 1], [0.0, 0.38]);
    const rightScale = interpolate(t, [0, 1], [0.88, 1.15]);

    const camProgress = interpolate(local, [0, 119], [0, 1], {
      easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });

    const camY = interpolate(camProgress, [0, 1], [3.8, 4.8]);
    const camZ = interpolate(camProgress, [0, 1], [13.8, 15.6]);
    const targetY = interpolate(camProgress, [0, 1], [2.2, 3.0]);

    return {
      shotIndex: 4,
      shotName: 'Shot 04: The Elevation',
      localFrame: local,
      camera: {
        position: [0, camY, camZ],
        target: [0, targetY, 0],
        fov: 34,
      },
      lighting: {
        preset: 'elevation',
        showFloor: true,
      },
      caseProps: {
        visible: true,
        position: [0, 1.8, 0],
        rotation: [0.03, -0.15, 0.2],
        scale: 1.05,
        opening: 1.65,
      },
      leftEarbudProps: {
        visible: true,
        parent: 'case',
        position: [leftX, leftY, leftZ],
        rotation: [leftRotX, leftRotY, leftRotZ],
        scale: leftScale,
      },
      rightEarbudProps: {
        visible: true,
        parent: 'case',
        position: [rightX, rightY, rightZ],
        rotation: [rightRotX, rightRotY, rightRotZ],
        scale: rightScale,
      },
      overlay: {
        textOpacity: 0,
        sceneOpacity: 1,
        background: '#070f14',
      },
    };
  }

  // SHOT 05: MACRO DETAILS (Frames 450 - 569)
  if (f <= SHOTS.SHOT_05_MACRO.to) {
    const local = f - SHOTS.SHOT_05_MACRO.from;

    if (local < 39) {
      // Sub-shot A: Silicone Tip & Acoustic Bore (local 0 - 38)
      const t = interpolate(local, [0, 38], [0, 1], {
        easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
        extrapolateLeft: 'clamp',
        extrapolateRight: 'clamp',
      });
      const camZ = interpolate(t, [0, 1], [3.2, 2.3]);
      const camY = interpolate(t, [0, 1], [1.3, 1.4]);

      return {
        shotIndex: 5,
        shotName: 'Shot 05A: Macro Nozzle',
        localFrame: local,
        camera: {
          position: [0, camY, camZ],
          target: [0, 1.35, 0],
          fov: 25,
        },
        lighting: {
          preset: 'macro-grille',
          showFloor: false,
        },
        caseProps: {
          visible: false,
          position: [0, 0, 0],
          rotation: [0, 0, 0],
          scale: 1.0,
          opening: 0,
        },
        leftEarbudProps: {visible: false, parent: 'world', position: [0, 0, 0], rotation: [0, 0, 0], scale: 1},
        rightEarbudProps: {visible: false, parent: 'world', position: [0, 0, 0], rotation: [0, 0, 0], scale: 1},
        macroEarbudProps: {
          visible: true,
          side: 1,
          position: [0, 1.35, 0],
          rotation: [-1.38, 0.28, 0],
          scale: 2.6,
          innerGroupPosition: [-0.14, 0.95, -0.04],
        },
        overlay: {
          textOpacity: 0,
          sceneOpacity: 1,
          background: '#050b10',
        },
      };
    } else if (local < 78) {
      // Sub-shot B: Glossy Touch Panel Tracking (local 39 - 77)
      const subFrame = local - 39;
      const t = interpolate(subFrame, [0, 38], [0, 1], {
        easing: Easing.bezier(0.3, 0.0, 0.2, 1.0),
        extrapolateLeft: 'clamp',
        extrapolateRight: 'clamp',
      });
      const camX = interpolate(t, [0, 1], [-0.4, 0.4]);
      const camY = interpolate(t, [0, 1], [1.9, 1.8]);
      const camZ = interpolate(t, [0, 1], [2.6, 2.3]);
      const targetX = interpolate(t, [0, 1], [-0.1, 0.1]);

      return {
        shotIndex: 5,
        shotName: 'Shot 05B: Macro Touch',
        localFrame: local,
        camera: {
          position: [camX, camY, camZ],
          target: [targetX, 1.5, 0.2],
          fov: 24,
        },
        lighting: {
          preset: 'macro-touch',
          highlightSweep: t,
          showFloor: false,
        },
        caseProps: {
          visible: false,
          position: [0, 0, 0],
          rotation: [0, 0, 0],
          scale: 1.0,
          opening: 0,
        },
        leftEarbudProps: {visible: false, parent: 'world', position: [0, 0, 0], rotation: [0, 0, 0], scale: 1},
        rightEarbudProps: {visible: false, parent: 'world', position: [0, 0, 0], rotation: [0, 0, 0], scale: 1},
        macroEarbudProps: {
          visible: true,
          side: -1,
          position: [0, 1.2, 0],
          rotation: [0.42, 0.15, -0.25],
          scale: 2.5,
        },
        overlay: {
          textOpacity: 0,
          sceneOpacity: 1,
          background: '#050a0f',
        },
      };
    } else {
      // Sub-shot C: Gold Charging Contacts (local 78 - 119)
      const subFrame = local - 78;
      const t = interpolate(subFrame, [0, 41], [0, 1], {
        easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
        extrapolateLeft: 'clamp',
        extrapolateRight: 'clamp',
      });
      const camX = interpolate(t, [0, 1], [-0.92, -0.86]);
      const camY = interpolate(t, [0, 1], [3.2, 2.7]);
      const camZ = interpolate(t, [0, 1], [1.1, 0.8]);

      return {
        shotIndex: 5,
        shotName: 'Shot 05C: Macro Contacts',
        localFrame: local,
        camera: {
          position: [camX, camY, camZ],
          target: [-0.89, 1.5, 0.1],
          fov: 22,
        },
        lighting: {
          preset: 'macro-contacts',
          showFloor: false,
        },
        caseProps: {
          visible: true,
          position: [0, 1.4, 0],
          rotation: [0.08, -0.2, 0],
          scale: 1.0,
          opening: 1.65,
        },
        leftEarbudProps: {visible: false, parent: 'case', position: [-0.89, 0.4, 0], rotation: [-0.2, 0, 0], scale: 0.88},
        rightEarbudProps: {visible: false, parent: 'case', position: [0.89, 0.4, 0], rotation: [-0.2, 0, 0], scale: 0.88},
        overlay: {
          textOpacity: 0,
          sceneOpacity: 1,
          background: '#060c12',
        },
      };
    }
  }

  // SHOT 06: THE HERO CLIMAX (Frames 570 - 659)
  if (f <= SHOTS.SHOT_06_HERO.to) {
    const local = f - SHOTS.SHOT_06_HERO.from;
    const progress = interpolate(local, [0, 89], [0, 1], {
      easing: Easing.bezier(0.25, 0.1, 0.25, 1.0),
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });

    const camZ = interpolate(progress, [0, 1], [15.0, 14.5]);
    const camY = interpolate(progress, [0, 1], [4.4, 4.3]);

    return {
      shotIndex: 6,
      shotName: 'Shot 06: The Hero Climax',
      localFrame: local,
      camera: {
        position: [0, camY, camZ],
        target: [0, 2.8, 0],
        fov: 34,
      },
      lighting: {
        preset: 'hero',
        showFloor: true,
      },
      caseProps: {
        visible: true,
        position: [-0.2, 1.9, 0],
        rotation: [0.03, -0.2, 0.31],
        scale: 1.05,
        opening: 1.65,
      },
      leftEarbudProps: {
        visible: true,
        parent: 'world',
        position: [-1.28, 5.24, 0.05],
        rotation: [0.52, -0.18, -0.46],
        scale: 1.15,
      },
      rightEarbudProps: {
        visible: true,
        parent: 'world',
        position: [0.94, 4.82, 0.08],
        rotation: [0.55, 0.3, 0.38],
        scale: 1.15,
      },
      overlay: {
        textOpacity: 0,
        sceneOpacity: 1,
        background: '#091218',
      },
    };
  }

  // SHOT 07: THE BRAND SIGNATURE (Frames 660 - 749)
  const local = f - SHOTS.SHOT_07_BRAND.from;
  const dockSpring = spring({
    frame: local,
    fps,
    config: {damping: 15, stiffness: 60, mass: 1.0},
  });

  const dockT = interpolate(dockSpring, [0, 1], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const leftX = interpolate(dockT, [0, 1], [-1.15, -0.89]);
  const leftY = interpolate(dockT, [0, 1], [3.2, 0.4]);
  const leftZ = interpolate(dockT, [0, 1], [0.05, 0.0]);
  const leftRotX = interpolate(dockT, [0, 1], [0.42, -0.2]);
  const leftRotZ = interpolate(dockT, [0, 1], [-0.35, 0.0]);
  const leftScale = interpolate(dockT, [0, 1], [1.12, 0.88]);

  const rightX = interpolate(dockT, [0, 1], [0.94, 0.89]);
  const rightY = interpolate(dockT, [0, 1], [3.0, 0.4]);
  const rightZ = interpolate(dockT, [0, 1], [0.08, 0.0]);
  const rightRotX = interpolate(dockT, [0, 1], [0.45, -0.2]);
  const rightRotZ = interpolate(dockT, [0, 1], [0.3, 0.0]);
  const rightScale = interpolate(dockT, [0, 1], [1.12, 0.88]);

  const closeSpring = spring({
    frame: local - 22,
    fps,
    config: {damping: 14, stiffness: 70, mass: 1.1},
  });

  const opening = interpolate(closeSpring, [0, 1], [1.65, 0.0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const textOpacity = interpolate(local, [38, 55], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const fadeOut = interpolate(local, [78, 89], [1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  return {
    shotIndex: 7,
    shotName: 'Shot 07: The Brand Signature',
    localFrame: local,
    camera: {
      position: [0, 4.8, 17.5],
      target: [0, 2.3, 0],
      fov: 34,
    },
    lighting: {
      preset: 'brand',
      showFloor: true,
    },
    caseProps: {
      visible: true,
      position: [0, 2.2, 0],
      rotation: [0.04, -0.12, 0.14],
      scale: 1.05,
      opening,
    },
    leftEarbudProps: {
      visible: true,
      parent: 'case',
      position: [leftX, leftY, leftZ],
      rotation: [leftRotX, 0, leftRotZ],
      scale: leftScale,
    },
    rightEarbudProps: {
      visible: true,
      parent: 'case',
      position: [rightX, rightY, rightZ],
      rotation: [rightRotX, 0, rightRotZ],
      scale: rightScale,
    },
    overlay: {
      textOpacity,
      sceneOpacity: fadeOut,
      background: '#070f14',
    },
  };
}
