import React, {useMemo} from 'react';
import {AbsoluteFill, Audio, staticFile, useCurrentFrame, useVideoConfig} from 'remotion';
import {ThreeCanvas} from '@remotion/three';
import * as THREE from 'three';
import {getShotState} from '../animation/shotController';
import {PersistentStudioScene} from '../components/PersistentStudioScene';

export const NovaAd: React.FC = () => {
  const frame = useCurrentFrame();
  const {width, height, fps} = useVideoConfig();

  // Evaluate deterministic shot state for the current global frame
  const shot = useMemo(() => getShotState(frame, fps), [frame, fps]);

  return (
    <AbsoluteFill
      style={{
        background: shot.overlay.background,
        opacity: shot.overlay.sceneOpacity,
        overflow: 'hidden',
      }}
    >
      {/* Synchronized Procedural Soundtrack */}
      <Audio src={staticFile('audio/nova-soundtrack.wav')} />

      {/* SINGLE PERSISTENT THREE.JS CANVAS ACROSS ALL 750 FRAMES
          Avoids multiple WebGL context unmounting, shader recompilation, and R3F context delays */}
      <ThreeCanvas
        width={width}
        height={height}
        gl={{
          antialias: true,
          alpha: false,
          toneMapping: THREE.ACESFilmicToneMapping,
          toneMappingExposure: 1.1,
          powerPreference: 'high-performance',
        }}
      >
        <PersistentStudioScene shot={shot} />
      </ThreeCanvas>

      {/* Brand Typography Overlay — Positioned strictly within Instagram Safe Areas */}
      {shot.overlay.textOpacity > 0 && (
        <div
          style={{
            position: 'absolute',
            inset: 0,
            opacity: shot.overlay.textOpacity,
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'flex-end',
            alignItems: 'center',
            paddingBottom: 380, // Safe from Instagram bottom overlay (caption, audio, handles)
            paddingLeft: 100,
            paddingRight: 180, // Safe from right-side action buttons (like, comment, share)
            pointerEvents: 'none',
          }}
        >
          <div
            style={{
              fontFamily:
                '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif',
              fontSize: 76,
              fontWeight: 200,
              letterSpacing: 24,
              color: '#ffffff',
              textTransform: 'uppercase',
              textShadow: '0 0 35px rgba(110, 215, 255, 0.45)',
              marginBottom: 14,
            }}
          >
            NOVA
          </div>
          <div
            style={{
              fontFamily:
                '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif',
              fontSize: 20,
              fontWeight: 400,
              letterSpacing: 8,
              color: '#90c6df',
              textTransform: 'uppercase',
              opacity: 0.95,
            }}
          >
            Engineered for Every Moment.
          </div>
        </div>
      )}
    </AbsoluteFill>
  );
};
