import React from "react";
import {ThreeCanvas} from "@remotion/three";
import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from "remotion";
import * as THREE from "three";
import {
  assetConfigs,
  createDisk,
  createFlatRing,
  createPhone,
  createSphere,
  createWallpaperTexture,
  phoneConfig,
  setupLighting,
  STUDIO_BACKGROUND_COLOR,
  type AssetConfig,
} from "./PhoneSceneReconstruction";

type VerticalAsset = "all";
type RisingAccentKind = "star" | "cube" | "diamond" | "tetrahedron";

type RisingAccentSpec = {
  readonly kind: RisingAccentKind;
  readonly color: string;
  readonly size: number;
  readonly startX: number;
  readonly endX: number;
  readonly phase: number;
  readonly turns: number;
  readonly rotation: [number, number, number];
};

const FLOW_DURATION_SECONDS = 40;
const FLOW_TRAVEL = 42;
const PORTRAIT_VIEW_BOTTOM = -10;
const PORTRAIT_VIEW_TOP = 10;
const FADE_DISTANCE = 1.9;

const FLOW_PHASES: Record<keyof typeof VERTICAL_CONFIGS, number> = {
  "disk-a": 0 / 17,
  "ring-a": 1 / 17,
  "disk-d": 2 / 17,
  "sphere-a": 3 / 17,
  "ring-b": 4 / 17,
  "disk-b": 5 / 17,
  "sphere-e": 6 / 17,
  "disk-c": 7 / 17,
  "ring-c": 8 / 17,
  "sphere-b": 9 / 17,
  "disk-e": 10 / 17,
  "sphere-f": 11 / 17,
  "disk-f": 12 / 17,
  "sphere-c": 13 / 17,
  "sphere-h": 14 / 17,
  "sphere-g": 15 / 17,
  "sphere-d": 16 / 17,
};

const ROTATION_CYCLES: Record<keyof typeof VERTICAL_CONFIGS, number> = {
  "disk-a": 1,
  "ring-a": -1,
  "disk-d": 1,
  "sphere-a": -2,
  "ring-b": 1,
  "disk-b": -1,
  "sphere-e": 2,
  "disk-c": 1,
  "ring-c": -1,
  "sphere-b": 2,
  "disk-e": 1,
  "sphere-f": -2,
  "disk-f": -1,
  "sphere-c": 2,
  "sphere-h": -2,
  "sphere-g": 2,
  "sphere-d": -2,
};

const RISING_ACCENT_DURATION_SECONDS = 12;
const RISING_ACCENTS: readonly RisingAccentSpec[] = [
  {kind: "star", color: "#ff5d7d", size: 0.18, startX: -1.0, endX: -0.78, phase: 0.02, turns: 1, rotation: [0.2, 0.1, 0.3]},
  {kind: "cube", color: "#35b8ff", size: 0.2, startX: 0.75, endX: 0.98, phase: 0.14, turns: -1, rotation: [0.1, 0.3, 0.2]},
  {kind: "diamond", color: "#ffc83d", size: 0.22, startX: -0.35, endX: -0.12, phase: 0.26, turns: 1, rotation: [0.3, 0.2, 0.1]},
  {kind: "star", color: "#9c6cff", size: 0.16, startX: 0.2, endX: 0.48, phase: 0.38, turns: -1, rotation: [0.1, 0.2, 0.4]},
  {kind: "tetrahedron", color: "#42e6a4", size: 0.2, startX: -0.75, endX: -0.55, phase: 0.5, turns: 1, rotation: [0.2, 0.4, 0.1]},
  {kind: "cube", color: "#ff884d", size: 0.17, startX: 0.52, endX: 0.32, phase: 0.62, turns: -1, rotation: [0.3, 0.1, 0.2]},
  {kind: "diamond", color: "#ee4cc8", size: 0.18, startX: -0.05, endX: 0.18, phase: 0.74, turns: 1, rotation: [0.1, 0.5, 0.2]},
  {kind: "star", color: "#6ee7ff", size: 0.2, startX: 0.95, endX: 0.7, phase: 0.86, turns: -1, rotation: [0.3, 0.2, 0.3]},
];

const createStarShape = (radius: number) => {
  const shape = new THREE.Shape();
  const points = 10;
  for (let index = 0; index < points; index += 1) {
    const angle = -Math.PI / 2 + (index * Math.PI) / 5;
    const pointRadius = index % 2 === 0 ? radius : radius * 0.43;
    const x = Math.cos(angle) * pointRadius;
    const y = Math.sin(angle) * pointRadius;
    if (index === 0) {
      shape.moveTo(x, y);
    } else {
      shape.lineTo(x, y);
    }
  }
  shape.closePath();
  return shape;
};

const createRisingAccent = (spec: RisingAccentSpec, progress: number, opacity: number) => {
  const easedProgress = interpolate(progress, [0, 1], [0, 1], {
    easing: Easing.inOut(Easing.ease),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const x = interpolate(easedProgress, [0, 1], [spec.startX, spec.endX]);
  const y = interpolate(easedProgress, [0, 1], [-3.18, 3.32]);
  const spin = Math.PI * 2 * spec.turns * progress;
  const rotation: [number, number, number] = [
    spec.rotation[0] + spin * 0.45,
    spec.rotation[1] + spin,
    spec.rotation[2] + spin * 0.7,
  ];
  const materialProps = {
    color: spec.color,
    roughness: 0.3,
    metalness: 0.08,
    clearcoat: 0.25,
    transparent: opacity < 1,
    opacity,
  };

  return (
    <group key={`${spec.kind}-${spec.color}`} position={[x, y, 0]} rotation={rotation}>
      {spec.kind === "star" ? (
        <mesh castShadow>
          <extrudeGeometry args={[createStarShape(spec.size), {depth: spec.size * 0.32, bevelEnabled: true, bevelSegments: 2, bevelSize: spec.size * 0.06, bevelThickness: spec.size * 0.05}]} />
          <meshPhysicalMaterial {...materialProps} />
        </mesh>
      ) : null}
      {spec.kind === "cube" ? (
        <mesh castShadow>
          <boxGeometry args={[spec.size * 1.55, spec.size * 1.55, spec.size * 1.55]} />
          <meshPhysicalMaterial {...materialProps} />
        </mesh>
      ) : null}
      {spec.kind === "diamond" ? (
        <mesh castShadow>
          <octahedronGeometry args={[spec.size, 0]} />
          <meshPhysicalMaterial {...materialProps} flatShading />
        </mesh>
      ) : null}
      {spec.kind === "tetrahedron" ? (
        <mesh castShadow>
          <tetrahedronGeometry args={[spec.size * 1.2, 0]} />
          <meshPhysicalMaterial {...materialProps} flatShading />
        </mesh>
      ) : null}
    </group>
  );
};

const RisingAccentField: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const durationInFrames = RISING_ACCENT_DURATION_SECONDS * fps;

  return (
    <group position={[0, 0.2, 1.35]} rotation={phoneConfig.rotation}>
      {RISING_ACCENTS.map((spec) => {
        const progress = (frame / durationInFrames + spec.phase) % 1;
        const opacity = interpolate(progress, [0, 0.1, 0.9, 1], [0, 1, 1, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        return createRisingAccent(spec, progress, opacity);
      })}
    </group>
  );
};

const verticalConfig = (
  name: Exclude<keyof typeof assetConfigs, never>,
  position: [number, number, number],
): AssetConfig => ({
  ...assetConfigs[name],
  position,
});

const VERTICAL_CONFIGS: Record<string, AssetConfig> = {
  "disk-a": verticalConfig("disk-a", [-5.0, 0.4, -0.1]),
  "disk-b": verticalConfig("disk-b", [-3.75, 0.3, 0.02]),
  "disk-c": verticalConfig("disk-c", [-2.65, 0.65, 0.04]),
  "disk-d": verticalConfig("disk-d", [3.55, 0.5, -0.04]),
  "disk-e": verticalConfig("disk-e", [5.05, 1.45, -0.08]),
  "disk-f": verticalConfig("disk-f", [4.25, -8.2, -0.1]),
  "ring-a": verticalConfig("ring-a", [0.8, 5.25, -0.05]),
  "ring-b": verticalConfig("ring-b", [4.15, 0.55, -0.04]),
  "ring-c": verticalConfig("ring-c", [-3.65, -8.15, -0.06]),
  "sphere-a": verticalConfig("sphere-a", [-5.25, 6.7, 0.1]),
  "sphere-b": verticalConfig("sphere-b", [-3.9, 4.45, 0.12]),
  "sphere-c": verticalConfig("sphere-c", [-4.55, -4.95, 0.12]),
  "sphere-d": verticalConfig("sphere-d", [-4.55, -7.8, 0.1]),
  "sphere-e": verticalConfig("sphere-e", [4.8, 6.6, 0.12]),
  "sphere-f": verticalConfig("sphere-f", [5.35, 4.5, 0.1]),
  "sphere-g": verticalConfig("sphere-g", [4.65, -4.1, 0.12]),
  "sphere-h": verticalConfig("sphere-h", [0.0, -7.35, 0.12]),
};

const wrapFlowOffset = (offset: number) => {
  const wrapped = (offset + FLOW_TRAVEL / 2) % FLOW_TRAVEL;
  return (wrapped < 0 ? wrapped + FLOW_TRAVEL : wrapped) - FLOW_TRAVEL / 2;
};

const animatedConfig = (
  name: keyof typeof VERTICAL_CONFIGS,
  flowOffset: number,
  progress: number,
): AssetConfig => {
  const base = VERTICAL_CONFIGS[name];
  const y = base.position[1] + wrapFlowOffset(flowOffset + FLOW_PHASES[name] * FLOW_TRAVEL);
  const fadeIn = interpolate(
    y,
    [PORTRAIT_VIEW_BOTTOM - FADE_DISTANCE, PORTRAIT_VIEW_BOTTOM + FADE_DISTANCE],
    [0, 1],
    {extrapolateLeft: "clamp", extrapolateRight: "clamp"},
  );
  const fadeOut = interpolate(
    y,
    [PORTRAIT_VIEW_TOP - FADE_DISTANCE, PORTRAIT_VIEW_TOP + FADE_DISTANCE],
    [1, 0],
    {extrapolateLeft: "clamp", extrapolateRight: "clamp"},
  );

  return {
    ...base,
    position: [base.position[0], y, base.position[2]],
    rotation: [
      base.rotation[0],
      base.rotation[1] + Math.PI * 2 * ROTATION_CYCLES[name] * progress,
      base.rotation[2],
    ],
    opacity: Math.min(fadeIn, fadeOut),
  };
};

const VerticalScene: React.FC<{readonly asset: VerticalAsset; readonly flowOffset?: number; readonly progress?: number; readonly showRisingAccents?: boolean}> = ({flowOffset, progress = 0, showRisingAccents = false}) => {
  const moving = flowOffset !== undefined;
  const config = (name: keyof typeof VERTICAL_CONFIGS) =>
    moving ? animatedConfig(name, flowOffset, progress) : VERTICAL_CONFIGS[name];

  return <>
    {setupLighting()}
    <mesh position={[0, 0, -2]}>
      <planeGeometry args={[24, 30]} />
      <meshBasicMaterial color={STUDIO_BACKGROUND_COLOR} />
    </mesh>
    {createPhone({position: [0, 0.2, 0.6], rotation: phoneConfig.rotation})}
    <group position={[0, 0.2, 0.6]} rotation={phoneConfig.rotation}>
      {createWallpaperTexture()}
    </group>
    {showRisingAccents ? <RisingAccentField /> : null}
    {createDisk(config("disk-a"))}
    {createDisk(config("disk-b"))}
    {createDisk(config("disk-c"))}
    {createDisk(config("disk-d"))}
    {createDisk(config("disk-e"))}
    {createDisk(config("disk-f"))}
    {createFlatRing(config("ring-a"))}
    {createFlatRing(config("ring-b"))}
    {createFlatRing(config("ring-c"))}
    {createSphere(config("sphere-a"))}
    {createSphere(config("sphere-b"))}
    {createSphere(config("sphere-c"))}
    {createSphere(config("sphere-d"))}
    {createSphere(config("sphere-e"))}
    {createSphere(config("sphere-f"))}
    {createSphere(config("sphere-g"))}
    {createSphere(config("sphere-h"))}
  </>
};

const AnimatedVerticalScene: React.FC<{readonly asset: VerticalAsset}> = ({asset}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const durationInFrames = FLOW_DURATION_SECONDS * fps;
  const progress = (frame % durationInFrames) / durationInFrames;
  const flowOffset = interpolate(
    progress,
    [0, 1],
    [-FLOW_TRAVEL / 2, FLOW_TRAVEL / 2],
    {easing: Easing.linear, extrapolateLeft: "clamp", extrapolateRight: "clamp"},
  );

  return <VerticalScene asset={asset} flowOffset={flowOffset} progress={progress} showRisingAccents />;
};

export const PhoneSceneVertical: React.FC<{readonly asset?: VerticalAsset}> = ({asset = "all"}) => {
  const {width, height} = useVideoConfig();
  return (
    <AbsoluteFill style={{backgroundColor: STUDIO_BACKGROUND_COLOR, overflow: "hidden"}}>
      <ThreeCanvas
        width={width}
        height={height}
        orthographic
        shadows
        dpr={1}
        camera={{position: [0, 0, 14], zoom: 96, near: 0.1, far: 50}}
        gl={{antialias: true, alpha: false, toneMapping: THREE.ACESFilmicToneMapping, toneMappingExposure: 0.9, outputColorSpace: THREE.SRGBColorSpace}}
        onCreated={({camera, gl}) => {
          camera.lookAt(0, 0, 0);
          camera.updateProjectionMatrix();
          gl.setClearColor(STUDIO_BACKGROUND_COLOR, 1);
        }}
      >
        <AnimatedVerticalScene asset={asset} />
      </ThreeCanvas>
    </AbsoluteFill>
  );
};

