function Rim({
  w,
  d,
  r,
  y,
  thickness = 0.012,
  material = M.seam,
}: {
  w: number;
  d: number;
  r: number;
  y: number;
  thickness?: number;
  material?: THREE.Material;
}) {
  const geo = useMemo(() => {
    const pts = perimeter(w, d, r).map((v) => new THREE.Vector3(v.x, y, v.y));
    pts.push(pts[0]);
    return new THREE.TubeGeometry(
      new THREE.CatmullRomCurve3(pts),
      160,
      thickness,
      8,
      false
    );
  }, [w, d, r, y, thickness]);
  return <mesh geometry={geo} material={material} />;
}

export function ChargingCase({opening = 1.65}: {opening?: number}) {
  return (
    <group>
      {/* Lower case tub & silver perimeter */}
      <mesh geometry={base} material={M.body} />
      <mesh geometry={band} material={M.silver} />
      <Rim w={3.50} d={1.84} r={0.73} y={0.365} />

      {/* Top deck with two recessed charging cavities */}
      <mesh position={[0, 0.535, 0]} geometry={deck} material={M.interior} />
      {[-0.89, 0.89].map((x) => (
        <group key={x} position={[x, 0.534, 0]}>
          <mesh geometry={well} material={M.interior} />
          <mesh position={[0, -0.41, 0]} rotation={[-Math.PI / 2, 0, 0]}>
            <circleGeometry args={[0.16, 48]} />
            <primitive object={M.interior} attach="material" />
          </mesh>
          {/* Gold charging contact pins */}
          {[0, 1].map((k) => (
            <mesh key={k} position={[0.10 + k * 0.13, -0.30, 0.10]}>
              <cylinderGeometry args={[0.026, 0.031, 0.08, 20]} />
              <primitive object={M.gold} attach="material" />
            </mesh>
          ))}
          <mesh position={[0.30, -0.20, 0.25]} rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[0.026, 0.036, 24]} />
            <primitive object={M.ink} attach="material" />
          </mesh>
        </group>
      ))}

      {/* Hinge assembly and open lid */}
      <group position={[0, 0.52, -0.76]}>
        {[-0.55, 0.55].map((x) => (
          <mesh key={x} rotation={[0, 0, Math.PI / 2]} position={[x, 0, 0]}>
            <cylinderGeometry args={[0.085, 0.085, 0.44, 32]} />
            <primitive object={M.silver} attach="material" />
          </mesh>
        ))}

        {/* Lid pivot: opening = 1.65 rad (~94.5 deg) stands tall and matches reference */}
        <group rotation={[-opening, 0, 0]}>
          <group position={[0, 0, 0.76]}>
            <mesh geometry={lidShell} material={M.body} />
            <mesh geometry={lidInner} material={M.interior} />
            <mesh position={[0, 0.118, 0]} geometry={lidPad} material={M.pad} />
            <Rim w={3.43} d={1.77} r={0.71} y={0.035} thickness={0.018} material={M.silver} />
            {/* Upper latch detail */}
            <mesh position={[0, 0.003, 0.69]} scale={[0.67, 0.025, 0.18]}>
              <sphereGeometry args={[1, 32, 16]} />
              <primitive object={M.body} attach="material" />
            </mesh>
          </group>
        </group>
      </group>

      {/* Front latch recess & silver accent */}
      <mesh position={[0.50, 0.43, 0.885]} scale={[0.50, 0.042, 0.025]}>
        <sphereGeometry args={[1, 48, 16]} />
        <primitive object={M.silver} attach="material" />
      </mesh>
      <mesh position={[0.50, 0.44, 0.905]} scale={[0.43, 0.018, 0.008]}>
        <sphereGeometry args={[1, 48, 16]} />
        <primitive object={M.pad} attach="material" />
      </mesh>

      {/* Four electric blue front LEDs */}
      {[0, 1, 2, 3].map((i) => (
        <mesh key={i} position={[0.33 + i * 0.165, 0.175, 0.925]}>
          <sphereGeometry args={[0.014, 16, 12]} />
          <primitive object={M.led} attach="material" />
        </mesh>
      ))}
    </group>
  );
}

export function Earbud({side = 1}: {side?: number}) {
  return (
    <group>
      {/* Ergonomic main contoured housing */}
      <mesh geometry={earbudBody} material={M.body} />

      {/* Outer touch panel assembly: angled oval face with subtle chamfered bezel */}
      <group position={[0, 0.32, 0.06]} rotation={[0.42, 0, 0]}>
        {/* Subtle dark titanium bezel (true oval geometry) */}
        <mesh position={[0, 0.012, 0]} rotation={[-Math.PI / 2, 0, 0]} geometry={touchBezel} material={M.darkMetal} />
        {/* Glossy black polished touch plate (true oval geometry) */}
        <mesh position={[0, 0.018, 0]} rotation={[-Math.PI / 2, 0, 0]} geometry={touchPlate} material={M.gloss} />
        {/* Subtle acoustic micro-apertures */}
        {Array.from({length: 8}, (_, i) => (
          <mesh
            key={i}
            position={[(i % 4 - 1.5) * 0.035, 0.022, 0.28 + Math.floor(i / 4) * 0.028]}
            material={M.ink}
          >
            <sphereGeometry args={[0.007, 8, 6]} />
          </mesh>
        ))}
      </group>

      {/* Angled sound nozzle stem & silicone ear tip */}
      <group position={[side * 0.14, -0.38, -0.04]} rotation={[0.22, 0, side * -0.16]}>
        {/* Glossy neck stem */}
        <mesh position={[0, -0.08, 0]} scale={[0.22, 0.26, 0.20]} material={M.gloss}>
          <sphereGeometry args={[1, 48, 24]} />
        </mesh>
        {/* Silicone tip */}
        <group position={[0, -0.22, 0]}>
          <mesh geometry={tip} material={M.silicone} />
          {/* Inner sound channel & acoustic grill */}
          <mesh position={[0, -0.52, 0]} rotation={[Math.PI / 2, 0, 0]} material={M.seam}>
            <circleGeometry args={[0.12, 32]} />
          </mesh>
          {Array.from({length: 5}, (_, i) => (
            <mesh
              key={i}
              position={[(i - 2) * 0.035, -0.523, 0]}
              material={M.ink}
            >
              <boxGeometry
                args={[
                  0.008,
                  0.004,
                  Math.sqrt(Math.max(0, 0.01 - ((i - 2) * 0.035) ** 2)) * 2,
                ]}
              />
            </mesh>
          ))}
        </group>
      </group>

      {/* Subtle procedural micro-markings on the earbud flank */}
      {[0, 1, 2].map((row) => (
        <group
          key={row}
          position={[side * 0.32, -0.02 - row * 0.055, 0.26]}
          rotation={[0, side * 0.55, -0.1]}
        >
          {[0, 1, 2, 3].map((i) => (
            <mesh key={i} position={[i * 0.035, 0, 0]} material={M.ink}>
              <boxGeometry args={[0.022, 0.009, 0.003]} />
            </mesh>
          ))}
        </group>
      ))}
    </group>
  );
}
