export const createWallpaperTexture = () => (
  <group>
    <RoundedBox args={[3.18, 5.14, 0.04]} radius={0.23} smoothness={6} position={[0, 0, 0.25]}>
      <shaderMaterial
        uniforms={{
          uTop: {value: new THREE.Color("#777680")},
          uBottom: {value: new THREE.Color("#393b42")},
        }}
        vertexShader={`varying vec2 vUv; void main(){vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`}
        fragmentShader={`
          varying vec2 vUv;
          uniform vec3 uTop;
          uniform vec3 uBottom;
          void main(){
            vec3 color=mix(uBottom,uTop,vUv.y*0.9+0.08);
            color+=vec3(0.035)*smoothstep(0.0,0.55,vUv.y);
            gl_FragColor=vec4(color,1.0);
          }
        `}
      />
    </RoundedBox>
    <mesh position={[0.0, 1.45, 0.3]} scale={[0.45, 0.58, 0.08]}>
      <sphereGeometry args={[1, 40, 24]} />
      <meshStandardMaterial color="#e5e5e8" roughness={0.72} />
    </mesh>
    <mesh position={[0.58, 0.48, 0.3]} scale={[0.16, 0.2, 0.06]}>
      <sphereGeometry args={[1, 32, 20]} />
      <meshStandardMaterial color="#d8d8dc" roughness={0.74} />
    </mesh>
    <mesh position={[-0.58, -1.62, 0.29]} scale={[1.16, 1.24, 0.12]}>
      <sphereGeometry args={[1, 48, 28]} />
      <meshStandardMaterial color="#bfc1c6" roughness={0.78} />
    </mesh>
  </group>
);

