export const createDisk = (config: AssetConfig) => (
  <mesh castShadow receiveShadow position={config.position} rotation={[Math.PI / 2 + config.rotation[0], config.rotation[1], config.rotation[2]]} scale={config.scale}>
    <cylinderGeometry args={[config.radius ?? 1, config.radius ?? 1, config.depth ?? 0.12, 64]} />
    <meshPhysicalMaterial
      color={config.color}
      roughness={config.roughness}
      metalness={config.metalness}
      clearcoat={0.22}
      transparent={config.opacity !== undefined && config.opacity < 1}
      opacity={config.opacity ?? 1}
    />
  </mesh>
);

const createRingShape = (outer: number, inner: number) => {
  const shape = new THREE.Shape();
  shape.absarc(0, 0, outer, 0, Math.PI * 2, false);
  const hole = new THREE.Path();
  hole.absarc(0, 0, inner, 0, Math.PI * 2, true);
  shape.holes.push(hole);
  return shape;
};

export const createFlatRing = (config: AssetConfig) => (
  <mesh castShadow receiveShadow position={config.position} rotation={config.rotation} scale={config.scale}>
    <extrudeGeometry args={[createRingShape(config.radius ?? 1.4, (config.radius ?? 1.4) * 0.82), {depth: config.depth ?? 0.14, bevelEnabled: true, bevelSegments: 2, bevelSize: 0.025, bevelThickness: 0.025}]} />
    <meshPhysicalMaterial
      color={config.color}
      roughness={config.roughness}
      metalness={config.metalness}
      clearcoat={0.4}
      transparent={config.opacity !== undefined && config.opacity < 1}
      opacity={config.opacity ?? 1}
    />
  </mesh>
);

export const createSphere = (config: AssetConfig) => (
  <mesh castShadow receiveShadow position={config.position} rotation={config.rotation} scale={config.scale}>
    <sphereGeometry args={[config.radius ?? 0.3, 48, 32]} />
    <meshPhysicalMaterial
      color={config.color}
      roughness={config.roughness}
      metalness={config.metalness}
      clearcoat={0.14}
      transparent={config.opacity !== undefined && config.opacity < 1}
      opacity={config.opacity ?? 1}
    />
  </mesh>
);

export const setupLighting = () => (
  <>
    <ambientLight intensity={0.34} color="#a7a59d" />
    <hemisphereLight intensity={0.28} color="#c4c4bd" groundColor="#20221f" />
    <directionalLight castShadow position={[-5, 5, 8]} intensity={1.65} color="#e7e6df" shadow-mapSize={[2048, 2048]} />
    <directionalLight position={[4, 1, 6]} intensity={0.36} color="#a9bfd0" />
  </>
);

export const setupCamera = () => ({position: [0, 0, 12] as Vec3, zoom: 76, near: 0.1, far: 50});

const PhoneScene: React.FC<{readonly asset: PhoneAsset}> = ({asset}) => {
  const show = (name: PhoneAsset) => asset === "all" || asset === name;
  const showPhone = show("phone");
  const showWallpaper = show("wallpaper");
  return (
    <>
      {setupLighting()}
      <mesh position={[0, 0, -2]}>
        <planeGeometry args={[30, 20]} />
        <meshBasicMaterial color={STUDIO_BACKGROUND_COLOR} />
      </mesh>
      {showPhone ? createPhone(phoneConfig) : null}
      {showWallpaper ? <group position={phoneConfig.position} rotation={phoneConfig.rotation}>{createWallpaperTexture()}</group> : null}
      {show("disk-a") ? createDisk(assetConfigs["disk-a"]) : null}
      {show("disk-b") ? createDisk(assetConfigs["disk-b"]) : null}
      {show("disk-c") ? createDisk(assetConfigs["disk-c"]) : null}
      {show("disk-d") ? createDisk(assetConfigs["disk-d"]) : null}
      {show("disk-e") ? createDisk(assetConfigs["disk-e"]) : null}
      {show("disk-f") ? createDisk(assetConfigs["disk-f"]) : null}
      {show("ring-a") ? createFlatRing(assetConfigs["ring-a"]) : null}
      {show("ring-b") ? createFlatRing(assetConfigs["ring-b"]) : null}
      {show("ring-c") ? createFlatRing(assetConfigs["ring-c"]) : null}
      {show("sphere-a") ? createSphere(assetConfigs["sphere-a"]) : null}
      {show("sphere-b") ? createSphere(assetConfigs["sphere-b"]) : null}
      {show("sphere-c") ? createSphere(assetConfigs["sphere-c"]) : null}
      {show("sphere-d") ? createSphere(assetConfigs["sphere-d"]) : null}
      {show("sphere-e") ? createSphere(assetConfigs["sphere-e"]) : null}
      {show("sphere-f") ? createSphere(assetConfigs["sphere-f"]) : null}
      {show("sphere-g") ? createSphere(assetConfigs["sphere-g"]) : null}
      {show("sphere-h") ? createSphere(assetConfigs["sphere-h"]) : null}
    </>
  );
};

export const PhoneSceneReconstruction: React.FC<{readonly asset?: PhoneAsset}> = ({asset = "all"}) => {
  const {width, height} = useVideoConfig();
  return (
    <AbsoluteFill style={{backgroundColor: STUDIO_BACKGROUND_COLOR, overflow: "hidden"}}>
      <ThreeCanvas
        width={width}
        height={height}
        orthographic
        shadows
        dpr={1}
        camera={setupCamera()}
        gl={{antialias: true, alpha: false, toneMapping: THREE.ACESFilmicToneMapping, toneMappingExposure: 0.9, outputColorSpace: THREE.SRGBColorSpace}}
        onCreated={({camera, gl}) => {
          camera.lookAt(0, 0, 0);
          camera.updateProjectionMatrix();
          gl.setClearColor(STUDIO_BACKGROUND_COLOR, 1);
        }}
      >
        <PhoneScene asset={asset} />
      </ThreeCanvas>
    </AbsoluteFill>
  );
};
