const bridgeFrames = 12;

const SceneBridge: React.FC<{ children: React.ReactNode; duration: number }> = ({
  children,
  duration,
}) => {
  const frame = useCurrentFrame();
  const opacity = interpolate(
    frame,
    [0, bridgeFrames, duration - bridgeFrames, duration],
    [1, 0, 0, 1],
    { easing: Easing.inOut(Easing.ease), extrapolateRight: "clamp" },
  );

  return (
    <AbsoluteFill>
      {children}
      <AbsoluteFill style={{ backgroundColor: "#100c18", opacity }} />
    </AbsoluteFill>
  );
};

const FilmEndCard: React.FC = () => {
  const frame = useCurrentFrame();
  const bowlOpacity = interpolate(frame, [0, 12, 130, 150], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const bowlScale = interpolate(frame, [0, 20], [0.86, 1], {
    easing: Easing.out(Easing.back(1.5)),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        alignItems: "center",
        justifyContent: "center",
        background:
          "radial-gradient(ellipse at 50% 42%, #443057 0%, #1d1a2d 52%, #10121d 100%)",
        color: "#fff1d0",
        fontFamily: "Arial, sans-serif",
        textAlign: "center",
      }}
    >
      <div style={{ opacity: bowlOpacity, transform: `scale(${bowlScale})` }}>
        <div
          style={{
            color: "#ffbd62",
            fontSize: 30,
            fontWeight: 800,
            letterSpacing: 8,
            marginBottom: 24,
          }}
        >
          NEXT YEAR…
        </div>
        <div
          style={{
            fontSize: 66,
            fontWeight: 900,
            lineHeight: 1.08,
            textShadow: "0 6px 28px #ff781d66",
          }}
        >
          WE’RE BUYING
          <br />
          A BOWL.
        </div>
        <div style={{ fontSize: 48, marginTop: 27 }}>🍬 🎃 🍬</div>
      </div>
    </AbsoluteFill>
  );
};

