import React, { useLayoutEffect, useRef } from "react";

import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from "remotion";

import * as THREE from "three";

export const CandyMachineTest: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);

  const machineRef = useRef<THREE.Group | null>(null);
  const candyRef = useRef<THREE.Group[]>([]);
  const buttonRef = useRef<THREE.Mesh | null>(null);
  const armRef = useRef<THREE.Group | null>(null);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color("#111521");

    const camera = new THREE.PerspectiveCamera(
      40,
      16 / 9,
      0.1,
      100
    );

    camera.position.set(7, 5, 11);
    camera.lookAt(0, 2, 0);

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
    });

    renderer.setSize(1280, 720, false);
    renderer.setPixelRatio(1);

    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;

    rendererRef.current = renderer;
    sceneRef.current = scene;
    cameraRef.current = camera;

    // LIGHTING

    scene.add(new THREE.AmbientLight(0xffffff, 1.8));

    const light = new THREE.DirectionalLight(0xffc27c, 4);
    light.position.set(-4, 8, 5);
    scene.add(light);

    const blueLight = new THREE.PointLight(0x4488ff, 100);
    blueLight.position.set(4, 3, -3);
    scene.add(blueLight);

    // FLOOR

    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(30, 30),
      new THREE.MeshStandardMaterial({ color: "#252a36" })
    );

    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -0.1;
    scene.add(floor);

    // MACHINE

    const machine = new THREE.Group();
    machineRef.current = machine;
    scene.add(machine);

    const bronze = new THREE.MeshStandardMaterial({
      color: "#b27a42",
      metalness: 0.8,
      roughness: 0.25,
    });

    const gold = new THREE.MeshStandardMaterial({
      color: "#f2bc50",
      metalness: 0.7,
      roughness: 0.25,
    });

    // BASE

    const base = new THREE.Mesh(
      new THREE.CylinderGeometry(1.7, 1.9, 0.4, 16),
      bronze
    );

    base.position.y = 0.6;
    machine.add(base);

    // SHAFT

    const shaft = new THREE.Mesh(
      new THREE.CylinderGeometry(0.25, 0.3, 3.5, 24),
      gold
    );

    shaft.position.y = 2.5;
    machine.add(shaft);

    // ROTATING ARMS

    const arms = new THREE.Group();
    arms.position.y = 4.1;

    machine.add(arms);
    armRef.current = arms;

    for (let i = 0; i < 3; i++) {
      const arm = new THREE.Group();

      const beam = new THREE.Mesh(
        new THREE.BoxGeometry(2.8, 0.18, 0.2),
        bronze
      );

      beam.position.x = 1.4;
      arm.add(beam);

      const hook = new THREE.Mesh(
        new THREE.TorusGeometry(0.25, 0.07, 12, 32),
        gold
      );

      hook.position.set(2.8, -0.3, 0);
      hook.rotation.x = Math.PI / 2;

      arm.add(hook);

      arm.rotation.y = (i / 3) * Math.PI * 2;

      arms.add(arm);
    }

    // CANDY

    const candyColors = [
      "#ff4242",
      "#ffd43b",
      "#42a5ff",
      "#a65cff",
      "#ff8c32",
      "#47d17c",
    ];

    const candyObjects: THREE.Group[] = [];

    for (let i = 0; i < 22; i++) {
      const candy = new THREE.Group();

      const material = new THREE.MeshStandardMaterial({
        color: candyColors[i % candyColors.length],
        roughness: 0.3,
      });

      const body = new THREE.Mesh(
        new THREE.SphereGeometry(0.16, 16, 16),
        material
      );

      candy.add(body);

      const wrapper = new THREE.Mesh(
        new THREE.ConeGeometry(0.12, 0.25, 8),
        material
      );

      wrapper.position.x = 0.18;
      wrapper.rotation.z = -Math.PI / 2;

      candy.add(wrapper);

      candy.position.set(
        Math.sin(i * 2.4) * 1.5,
        2 + (i % 4) * 0.4,
        Math.cos(i * 2.4) * 1.5
      );

      scene.add(candy);
      candyObjects.push(candy);
    }

    candyRef.current = candyObjects;

    // RED BUTTON

    const button = new THREE.Mesh(
      new THREE.CylinderGeometry(0.35, 0.4, 0.22, 32),
      new THREE.MeshStandardMaterial({
        color: "#e52424",
        roughness: 0.25,
        emissive: "#580000",
      })
    );

    button.position.set(2.8, 1.4, 1);
    buttonRef.current = button;

    scene.add(button);

    return () => {
      scene.clear();
      renderer.dispose();

      rendererRef.current = null;
      sceneRef.current = null;
      cameraRef.current = null;
      machineRef.current = null;
      armRef.current = null;
      buttonRef.current = null;
      candyRef.current = [];
    };
  }, []);

  // FRAME-BASED ANIMATION

  useLayoutEffect(() => {
    const renderer = rendererRef.current;
    const scene = sceneRef.current;
    const camera = cameraRef.current;

    if (!renderer || !scene || !camera) return;

    const time = frame / fps;

    // MACHINE STARTS

    const activation = interpolate(
      frame,
      [90, 120],
      [0, 1],
      {
        easing: Easing.out(Easing.ease),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    );

    if (armRef.current) {
      armRef.current.rotation.y =
        activation * time * 12;
    }

    // BUTTON PRESS

    if (buttonRef.current) {
      const press = interpolate(
        frame,
        [65, 78, 90],
        [0, 0.4, 0],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }
      );

      buttonRef.current.position.y = 1.4 - press;
    }

    // MACHINE SHAKING

    if (machineRef.current) {
      const shake = interpolate(
        frame,
        [120, 170],
        [0, 1],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }
      );

      machineRef.current.position.x =
        Math.sin(time * 35) * 0.1 * shake;

      machineRef.current.rotation.z =
        Math.sin(time * 24) * 0.035 * shake;
    }

    // CANDY EXPLOSION

    candyRef.current.forEach((candy, index) => {
      const start = 125 + index * 2;

      const progress = interpolate(
        frame,
        [start, start + 70],
        [0, 1],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }
      );

      candy.position.x =
        Math.sin(index * 2.4) * 1.5 +
        progress * Math.sin(index * 4) * 3;

      candy.position.y =
        2 + (index % 4) * 0.4 +
        progress * 3 -
        progress * progress * 5;

      candy.position.z =
        Math.cos(index * 2.4) * 1.5 +
        progress * Math.cos(index * 3) * 3;

      candy.rotation.x = time * (index + 2);
      candy.rotation.z = time * (index + 1);
    });

    // CAMERA SHAKE

    const cameraShake = interpolate(
      frame,
      [120, 160],
      [0, 1],
      {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    );

    camera.position.x =
      7 + Math.sin(time * 30) * 0.12 * cameraShake;

    camera.lookAt(0, 2, 0);

    renderer.render(scene, camera);
  }, [frame, fps]);

  const titleOpacity = interpolate(
    frame,
    [0, 20, 185, 220],
    [0, 1, 1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: "#111521" }}>
      <canvas
        ref={canvasRef}
        style={{ width: "100%", height: "100%" }}
      />

      <div
        style={{
          position: "absolute",
          top: 35,
          width: "100%",
          textAlign: "center",
          fontSize: 44,
          fontWeight: 900,
          color: "#ffcf75",
          fontFamily: "Arial",
          letterSpacing: 4,
          opacity: titleOpacity,
          textShadow: "0 4px 18px #ff681c",
        }}
      >
        THE FIRST TEST!
      </div>

      <div
        style={{
          position: "absolute",
          bottom: 35,
          width: "100%",
          textAlign: "center",
          fontSize: 23,
          color: "#ffffff",
          letterSpacing: 3,
          opacity: titleOpacity,
        }}
      >
        SOMETHING IS NOT RIGHT...
      </div>
    </AbsoluteFill>
  );
};