import React, { useLayoutEffect, useRef } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from "remotion";

import * as THREE from "three";

export const CandyMachine: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);

  const machineRef = useRef<THREE.Group | null>(null);
  const armsRef = useRef<THREE.Group | null>(null);
  const wheelsRef = useRef<THREE.Group[]>([]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color("#111521");

    const camera = new THREE.PerspectiveCamera(
      40,
      16 / 9,
      0.1,
      100
    );

    camera.position.set(7, 6, 11);
    camera.lookAt(0, 2, 0);

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
    });

    renderer.setSize(1280, 720, false);
    renderer.setPixelRatio(1);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;

    rendererRef.current = renderer;
    sceneRef.current = scene;
    cameraRef.current = camera;

    // MATERIALS

    const bronze = new THREE.MeshStandardMaterial({
      color: "#a76a32",
      metalness: 0.85,
      roughness: 0.25,
    });

    const darkMetal = new THREE.MeshStandardMaterial({
      color: "#343a43",
      metalness: 0.9,
      roughness: 0.3,
    });

    const gold = new THREE.MeshStandardMaterial({
      color: "#e7b34e",
      metalness: 0.8,
      roughness: 0.2,
    });

    const candyMaterials = [
      new THREE.MeshStandardMaterial({ color: "#ff4141" }),
      new THREE.MeshStandardMaterial({ color: "#42b9ff" }),
      new THREE.MeshStandardMaterial({ color: "#ffe052" }),
      new THREE.MeshStandardMaterial({ color: "#8d55d9" }),
    ];

    // LIGHTING

    scene.add(new THREE.AmbientLight(0xffffff, 1.5));

    const keyLight = new THREE.DirectionalLight(
      0xffd5a0,
      3
    );

    keyLight.position.set(-5, 8, 6);
    scene.add(keyLight);

    const blueLight = new THREE.PointLight(
      0x4488ff,
      90
    );

    blueLight.position.set(4, 3, -4);
    scene.add(blueLight);

    // FLOOR

    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(30, 30),
      new THREE.MeshStandardMaterial({
        color: "#282b35",
        roughness: 0.9,
      })
    );

    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -0.1;
    scene.add(floor);

    // MAIN MACHINE

    const machine = new THREE.Group();

    scene.add(machine);
    machineRef.current = machine;

    // BASE

    const base = new THREE.Mesh(
      new THREE.CylinderGeometry(1.7, 1.9, 0.35, 12),
      bronze
    );

    base.position.y = 0.65;
    machine.add(base);

    // CENTRAL SHAFT

    const shaft = new THREE.Mesh(
      new THREE.CylinderGeometry(0.25, 0.3, 3.4, 24),
      gold
    );

    shaft.position.y = 2.5;
    machine.add(shaft);

    // CENTRAL TOP HUB

    const hub = new THREE.Mesh(
      new THREE.SphereGeometry(0.55, 32, 32),
      bronze
    );

    hub.position.y = 4.2;
    machine.add(hub);

    // THREE ROTATING ARMS

    const arms = new THREE.Group();

    arms.position.y = 4.1;
    machine.add(arms);

    armsRef.current = arms;

    for (let i = 0; i < 3; i++) {
      const arm = new THREE.Group();

      const angle = (i / 3) * Math.PI * 2;

      const beam = new THREE.Mesh(
        new THREE.BoxGeometry(2.6, 0.18, 0.2),
        bronze
      );

      beam.position.x = 1.3;
      arm.add(beam);

      // OUTER HOOK

      const hook = new THREE.Mesh(
        new THREE.TorusGeometry(0.25, 0.07, 12, 32),
        gold
      );

      hook.position.set(2.55, -0.25, 0);
      hook.rotation.x = Math.PI / 2;

      arm.add(hook);

      arm.rotation.y = angle;

      arms.add(arm);
    }

    // FOUR WHEELS

    const wheels: THREE.Group[] = [];

    for (const x of [-1.45, 1.45]) {
      for (const z of [-0.85, 0.85]) {
        const wheelGroup = new THREE.Group();

        const wheel = new THREE.Mesh(
          new THREE.CylinderGeometry(
            0.48,
            0.48,
            0.25,
            32
          ),
          darkMetal
        );

        wheel.rotation.z = Math.PI / 2;
        wheelGroup.add(wheel);

        const axle = new THREE.Mesh(
          new THREE.CylinderGeometry(
            0.13,
            0.13,
            0.3,
            16
          ),
          gold
        );

        axle.rotation.z = Math.PI / 2;
        wheelGroup.add(axle);

        wheelGroup.position.set(x, 0.4, z);

        machine.add(wheelGroup);
        wheels.push(wheelGroup);
      }
    }

    wheelsRef.current = wheels;

    // FOUR CANDY BUCKETS

    for (let i = 0; i < 4; i++) {
      const bucket = new THREE.Group();

      const body = new THREE.Mesh(
        new THREE.CylinderGeometry(
          0.35,
          0.25,
          0.55,
          24,
          1,
          true
        ),
        candyMaterials[i]
      );

      body.position.y = -0.3;
      bucket.add(body);

      const rim = new THREE.Mesh(
        new THREE.TorusGeometry(0.35, 0.035, 12, 32),
        gold
      );

      rim.rotation.x = Math.PI / 2;
      bucket.add(rim);

      const candy = new THREE.Mesh(
        new THREE.SphereGeometry(0.16, 16, 16),
        candyMaterials[(i + 1) % 4]
      );

      candy.position.y = 0.05;
      bucket.add(candy);

      const bucketAngle = (i / 4) * Math.PI * 2;

      bucket.position.set(
        Math.cos(bucketAngle) * 1.2,
        2.7,
        Math.sin(bucketAngle) * 1.2
      );

      machine.add(bucket);
    }

    // DECORATIVE GEARS

    for (let i = 0; i < 3; i++) {
      const gear = new THREE.Mesh(
        new THREE.TorusGeometry(0.45, 0.12, 12, 12),
        gold
      );

      gear.position.set(
        -1.2 + i * 1.2,
        1.2,
        1.65
      );

      machine.add(gear);
    }

    // PUMPKIN EMBLEM

    const emblem = new THREE.Mesh(
      new THREE.SphereGeometry(0.4, 24, 24),
      new THREE.MeshStandardMaterial({
        color: "#f47b22",
        roughness: 0.8,
        emissive: "#431200",
      })
    );

    emblem.position.set(0, 1.5, 1.8);
    machine.add(emblem);

    return () => {
      scene.clear();
      renderer.dispose();

      rendererRef.current = null;
      sceneRef.current = null;
      cameraRef.current = null;
      machineRef.current = null;
      armsRef.current = null;
      wheelsRef.current = [];
    };
  }, []);

  // ANIMATION

  useLayoutEffect(() => {
    const renderer = rendererRef.current;
    const scene = sceneRef.current;
    const camera = cameraRef.current;

    if (!renderer || !scene || !camera) return;

    const time = frame / fps;

    const assembly = interpolate(
      frame,
      [0, 60],
      [0, 1],
      {
        easing: Easing.out(Easing.ease),
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }
    );

    if (machineRef.current) {
      machineRef.current.scale.setScalar(assembly);
    }

    if (armsRef.current) {
      const spin = interpolate(
        frame,
        [90, 150],
        [0, Math.PI * 2],
        {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }
      );

      armsRef.current.rotation.y = spin;
    }

    wheelsRef.current.forEach((wheel) => {
      wheel.rotation.x = -time * 3;
    });

    camera.position.x = 7 + Math.sin(time * 0.5) * 0.6;
    camera.lookAt(0, 2.2, 0);

    renderer.render(scene, camera);
  }, [frame, fps]);

  const titleOpacity = interpolate(
    frame,
    [10, 30, 125, 155],
    [0, 1, 1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: "#111521" }}>
      <canvas
        ref={canvasRef}
        style={{ width: "100%", height: "100%" }}
      />

      <div
        style={{
          position: "absolute",
          top: 40,
          width: "100%",
          textAlign: "center",
          fontSize: 42,
          fontWeight: 900,
          color: "#f5bd67",
          fontFamily: "Arial",
          letterSpacing: 5,
          opacity: titleOpacity,
          textShadow: "0 4px 20px #d76c22",
        }}
      >
        THE CANDY MACHINE
      </div>

      <div
        style={{
          position: "absolute",
          bottom: 45,
          width: "100%",
          textAlign: "center",
          fontSize: 20,
          color: "#ffffff",
          letterSpacing: 3,
          opacity: titleOpacity,
        }}
      >
        ENGINEERING MEETS HALLOWEEN
      </div>
    </AbsoluteFill>
  );
};