import * as THREE from 'three';
import {WatchDisplay} from './WatchDisplay';
import {BatteryModule, PcbModule, RearCoverModule, RearSensorModule, ScrewSet} from './WatchInternals';
import {makeCaseProfile, makeGlassDome, makeRearProfile, makeWatchFaceRing} from '../geometry/watchGeometry';
import {watchMaterials as M} from '../materials/watchMaterials';

type LayerProps = {name: string; z: number; direction: [number, number, number]; children: React.ReactNode};
const Layer = ({name, z, direction, children}: LayerProps) => (
  <group name={name} position={[0, z * 2.35, z * 0.45]} scale={0.60} userData={{assembledPosition: [0, 0, 0], disassemblyDirection: direction}}>{children}</group>
);

const caseGeometry = makeCaseProfile();
const rearGeometry = makeRearProfile();
const glassGeometry = makeGlassDome();

export const ExplodedAssembly = () => (
  <group name="CHRONOS-X-exploded-assembly">
    <Layer name="01-protective-glass" z={3.45} direction={[0, 0, 1]}>
      <mesh geometry={glassGeometry} material={M.glass} />
      <mesh geometry={new THREE.TorusGeometry(1.99, 0.028, 8, 96)} position={[0, 0, 0.17]} material={M.glass} />
    </Layer>
    <Layer name="02-upper-bezel" z={2.65} direction={[0, 0, 1]}>
      <mesh geometry={makeWatchFaceRing(1.99, 2.22, 0)} material={M.bezelDark} />
      <mesh geometry={makeWatchFaceRing(2.01, 2.16, 0.05)} material={M.brushedMetal} />
      <mesh geometry={makeWatchFaceRing(2.04, 2.08, 0.08)} material={M.titaniumEdge} />
    </Layer>
    <Layer name="03-display-panel" z={1.88} direction={[0, 0, 1]}>
      <WatchDisplay />
    </Layer>
    <Layer name="04-display-mounting-frame" z={1.18} direction={[0, 0, 1]}>
      <mesh geometry={makeWatchFaceRing(1.91, 1.98, 0)} material={M.blackRubber} />
      <mesh geometry={makeWatchFaceRing(1.99, 2.06, 0.06)} material={M.titaniumEdge} />
    </Layer>
    <Layer name="05-internal-structural-ring" z={0.48} direction={[0, 0, 1]}>
      <mesh geometry={new THREE.TorusGeometry(2.02, 0.075, 10, 96)} material={M.titaniumEdge} />
      <mesh geometry={new THREE.TorusGeometry(1.80, 0.035, 8, 96)} material={M.copper} />
    </Layer>
    <Layer name="06-main-circuit-board" z={-0.28} direction={[0, 0, -1]}>
      <PcbModule />
    </Layer>
    <Layer name="07-battery" z={-1.04} direction={[0, 0, -1]}>
      <BatteryModule />
    </Layer>
    <Layer name="08-internal-housing" z={-1.82} direction={[0, 0, -1]}>
      <mesh geometry={caseGeometry} material={M.titanium} />
      <mesh geometry={rearGeometry} position={[0, 0, -0.07]} material={M.titaniumEdge} />
      <mesh position={[0, 0, 0.25]} material={M.blackRubber}>
        <circleGeometry args={[2.11, 96]} />
      </mesh>
    </Layer>
    <Layer name="09-rear-sensor-board" z={-2.62} direction={[0, 0, -1]}>
      <RearSensorModule z={0} />
    </Layer>
    <Layer name="10-rear-cover" z={-3.38} direction={[0, 0, -1]}>
      <RearCoverModule z={0} />
    </Layer>
    <Layer name="11-screws-fasteners" z={2.95} direction={[0, 0, 1]}>
      <ScrewSet z={0} />
    </Layer>
  </group>
);
