import * as THREE from 'three';

// Sampled rounded-rectangle perimeter with smooth corner transitions
export function perimeter(w: number, d: number, r: number, n = 128): THREE.Vector2[] {
  const out: THREE.Vector2[] = [];
  const hw = w / 2 - r;
  const hd = d / 2 - r;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const cosA = Math.cos(a);
    const sinA = Math.sin(a);
    out.push(
      new THREE.Vector2(
        Math.sign(cosA) * hw + r * cosA,
        Math.sign(sinA) * hd + r * sinA
      )
    );
  }
  return out;
}

type Ring = {
  y: number;
  w: number;
  d: number;
  r: number;
  x?: number;
  z?: number;
};

// Lofted shell between cross-section rings
export function loft(rings: Ring[], closeBottom = false, closeTop = false) {
  const p: number[] = [];
  const ix: number[] = [];
  const n = 128;

  for (const ring of rings) {
    const rx = ring.x ?? 0;
    const rz = ring.z ?? 0;
    for (const v of perimeter(ring.w, ring.d, ring.r, n)) {
      p.push(v.x + rx, ring.y, v.y + rz);
    }
  }

  for (let j = 0; j < rings.length - 1; j++) {
    for (let i = 0; i < n; i++) {
      const a = j * n + i;
      const b = j * n + ((i + 1) % n);
      const c = a + n;
      const d = b + n;
      ix.push(a, c, b, b, c, d);
    }
  }

  // To prevent Gouraud normal distortion from a single center vertex across sharp edges,
  // we generate separate concentric rings or separate flat planar caps.
  if (closeBottom) {
    const c = p.length / 3;
    const first = rings[0];
    p.push(first.x ?? 0, first.y, first.z ?? 0);
    for (let i = 0; i < n; i++) {
      ix.push(c, i, (i + 1) % n);
    }
  }

  if (closeTop) {
    const c = p.length / 3;
    const last = rings.at(-1)!;
    p.push(last.x ?? 0, last.y, last.z ?? 0);
    const o = (rings.length - 1) * n;
    for (let i = 0; i < n; i++) {
      ix.push(c, o + ((i + 1) % n), o + i);
    }
  }

  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  g.setIndex(ix);
  g.computeVertexNormals();
  return g;
}

export function roundedShape(w: number, d: number, r: number) {
  return new THREE.Shape(perimeter(w, d, r));
}

// Flat planar lid interior pad without radial crease distortion
export function lidPadGeometry(w: number, d: number, r: number) {
  const shape = roundedShape(w, d, r);
  const geo = new THREE.ShapeGeometry(shape, 64);
  geo.rotateX(-Math.PI / 2);
  return geo;
}

export function deckGeometry() {
  const s = roundedShape(3.40, 1.73, 0.68);
  for (const x of [-0.89, 0.89]) {
    const hole = new THREE.Path();
    hole.absellipse(x, 0, 0.64, 0.58, 0, Math.PI * 2, true, 0);
    s.holes.push(hole);
  }
  const g = new THREE.ShapeGeometry(s, 64);
  g.rotateX(-Math.PI / 2);
  return g;
}

export function wellGeometry() {
  // Smooth sculpted cavity for the earbuds
  const p: number[] = [];
  const idx: number[] = [];
  const n = 96;
  const m = 24;
  for (let j = 0; j <= m; j++) {
    const t = j / m;
    const r = 0.15 + 0.85 * Math.sin((t * Math.PI) / 2);
    const y = -0.42 * Math.cos((t * Math.PI) / 2);
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2;
      p.push(0.64 * r * Math.cos(a), y, 0.58 * r * Math.sin(a));
    }
  }
  for (let j = 0; j < m; j++) {
    for (let i = 0; i < n; i++) {
      const a = j * n + i;
      const b = j * n + ((i + 1) % n);
      idx.push(a, b, a + n, b, b + n, a + n);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

// Authentic ergonomic earbud body geometry (asymmetric contoured pebble with flat outer face)
export function earbudBodyGeometry() {
  const p: number[] = [];
  const idx: number[] = [];
  const n = 80;
  const m = 48;

  for (let j = 0; j <= m; j++) {
    const v = (j / m) * Math.PI;
    const sinV = Math.sin(v);
    const cosV = Math.cos(v);
    const y = cosV * 0.52;

    for (let i = 0; i <= n; i++) {
      const u = (i / n) * Math.PI * 2;
      const cosU = Math.cos(u);
      const sinU = Math.sin(u);

      // Ergonomic bean / ear contour shaping:
      // Flatten the top outer face where the touch panel rests
      const isTopFace = cosV > 0.4 && Math.abs(cosU) < 0.85;
      const flatten = isTopFace ? 0.88 : 1.0;

      // Asymmetric neck taper
      const taper = 1.0 - 0.22 * cosV;
      const rx = 0.44 * sinV * taper * flatten;
      const rz = 0.38 * sinV * (1.0 + 0.15 * cosU) * flatten;

      const px = rx * cosU + 0.05 * (1.0 - cosV);
      const py = y;
      const pz = rz * sinU;

      p.push(px, py, pz);
    }
  }

  for (let j = 0; j < m; j++) {
    for (let i = 0; i < n; i++) {
      const a = j * (n + 1) + i;
      const b = a + n + 1;
      idx.push(a, a + 1, b, b, a + 1, b + 1);
    }
  }

  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(p, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

// Ergonomic planar oval touch plate with subtle bevel
export function ovalTouchPlateGeometry(w = 0.56, h = 0.82, r = 0.26) {
  const shape = new THREE.Shape();
  const hw = w / 2 - r;
  const hh = h / 2 - r;
  shape.absarc(hw, hh, r, 0, Math.PI / 2, false);
  shape.absarc(-hw, hh, r, Math.PI / 2, Math.PI, false);
  shape.absarc(-hw, -hh, r, Math.PI, (Math.PI * 3) / 2, false);
  shape.absarc(hw, -hh, r, (Math.PI * 3) / 2, Math.PI * 2, false);

  const geo = new THREE.ShapeGeometry(shape, 48);
  return geo;
}

// Soft silicone umbrella tip geometry
export function tipGeometry() {
  return new THREE.LatheGeometry(
    [
      new THREE.Vector2(0.12, 0),
      new THREE.Vector2(0.14, -0.04),
      new THREE.Vector2(0.24, -0.09),
      new THREE.Vector2(0.31, -0.18),
      new THREE.Vector2(0.31, -0.27),
      new THREE.Vector2(0.26, -0.37),
      new THREE.Vector2(0.18, -0.42),
      new THREE.Vector2(0.13, -0.41),
      new THREE.Vector2(0.11, -0.35),
      new THREE.Vector2(0.11, -0.08),
      new THREE.Vector2(0.12, 0),
    ],
    96
  );
}
