import React, { useLayoutEffect, useRef } from "react";

import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from "remotion";

import * as THREE from "three";

export const HalloweenOpening: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);

  const sceneRef = useRef<THREE.Scene | null>(null);
  const kidsRef = useRef<THREE.Group[]>([]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color("#10172b");

    const camera = new THREE.PerspectiveCamera(
      45,
      16 / 9,
      0.1,
      100
    );

    camera.position.set(0, 4, 13);
    camera.lookAt(0, 1, 0);

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
    });

    renderer.setSize(1280, 720, false);
    renderer.setPixelRatio(1);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;

    rendererRef.current = renderer;
    cameraRef.current = camera;
    sceneRef.current = scene;

    // LIGHTING

    scene.add(new THREE.AmbientLight(0x8999cc, 1.8));

    const moonLight = new THREE.DirectionalLight(
      0x9abaff,
      3
    );

    moonLight.position.set(-5, 8, 5);
    scene.add(moonLight);

    const houseLight = new THREE.PointLight(
      0xffa34a,
      35,
      12
    );

    houseLight.position.set(0, 2, 2);
    scene.add(houseLight);

    // GROUND

    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(40, 40),
      new THREE.MeshStandardMaterial({
        color: "#202536",
        roughness: 1,
      })
    );

    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.05;

    scene.add(ground);

    // HOUSE

    const house = new THREE.Group();

    const wall = new THREE.Mesh(
      new THREE.BoxGeometry(4.5, 2.8, 0.5),
      new THREE.MeshStandardMaterial({
        color: "#45475c",
      })
    );

    wall.position.y = 1.4;
    house.add(wall);

    const roof = new THREE.Mesh(
      new THREE.ConeGeometry(3.5, 2.2, 4),
      new THREE.MeshStandardMaterial({
        color: "#242333",
      })
    );

    roof.rotation.y = Math.PI / 4;
    roof.position.y = 3.7;
    house.add(roof);

    // FRONT DOOR

    const door = new THREE.Mesh(
      new THREE.BoxGeometry(0.9, 1.8, 0.08),
      new THREE.MeshStandardMaterial({
        color: "#251a19",
      })
    );

    door.position.set(0, 0.9, 0.3);
    house.add(door);

    // WINDOWS

    for (const x of [-1.45, 1.45]) {
      const windowMesh = new THREE.Mesh(
        new THREE.BoxGeometry(0.85, 0.85, 0.08),
        new THREE.MeshBasicMaterial({
          color: "#ffbb55",
        })
      );

      windowMesh.position.set(x, 1.8, 0.3);
      house.add(windowMesh);
    }

    scene.add(house);

    // MOON

    const moon = new THREE.Mesh(
      new THREE.SphereGeometry(0.9, 32, 32),
      new THREE.MeshBasicMaterial({
        color: "#fff0bd",
      })
    );

    moon.position.set(-5, 5.5, -3);
    scene.add(moon);

    // PUMPKINS

    const pumpkins: THREE.Group[] = [];

    for (const x of [-3, 3, -2, 2]) {
      const pumpkin = new THREE.Group();

      const body = new THREE.Mesh(
        new THREE.SphereGeometry(0.55, 24, 24),
        new THREE.MeshStandardMaterial({
          color: "#ed711c",
          roughness: 0.85,
          emissive: "#4a1800",
        })
      );

      body.scale.set(1, 0.85, 0.85);
      pumpkin.add(body);

      const stem = new THREE.Mesh(
        new THREE.CylinderGeometry(
          0.07,
          0.1,
          0.3,
          8
        ),
        new THREE.MeshStandardMaterial({
          color: "#42602a",
        })
      );

      stem.position.y = 0.55;
      pumpkin.add(stem);

      pumpkin.position.set(x, 0.45, 2);

      scene.add(pumpkin);
      pumpkins.push(pumpkin);
    }

    // CHILDREN

    const kids: THREE.Group[] = [];

    const kidColors = [
      "#d94848",
      "#3476cc",
      "#9b59b6",
    ];

    for (let i = 0; i < 3; i++) {
      const kid = new THREE.Group();

      const body = new THREE.Mesh(
        new THREE.CylinderGeometry(
          0.25,
          0.35,
          0.9,
          16
        ),
        new THREE.MeshStandardMaterial({
          color: kidColors[i],
        })
      );

      body.position.y = 0.85;
      kid.add(body);

      const head = new THREE.Mesh(
        new THREE.SphereGeometry(0.3, 24, 24),
        new THREE.MeshStandardMaterial({
          color: "#e8b28d",
        })
      );

      head.position.y = 1.55;
      kid.add(head);

      const bucket = new THREE.Mesh(
        new THREE.CylinderGeometry(
          0.18,
          0.13,
          0.3,
          16
        ),
        new THREE.MeshStandardMaterial({
          color: "#ff941c",
        })
      );

      bucket.position.set(0.4, 0.55, 0.1);
      kid.add(bucket);

      kid.position.set(
        (i - 1) * 1.3,
        0,
        5 + i * 0.4
      );

      scene.add(kid);
      kids.push(kid);
    }

    kidsRef.current = kids;

    return () => {
      renderer.dispose();
      scene.clear();
      kidsRef.current = [];
      rendererRef.current = null;
      sceneRef.current = null;
      cameraRef.current = null;
    };

  }, []);

  // FRAME-ACCURATE ANIMATION

  useLayoutEffect(() => {
    const renderer = rendererRef.current;
    const camera = cameraRef.current;
    const scene = sceneRef.current;

    if (!renderer || !camera || !scene) return;

    const time = frame / fps;

    // Camera slowly approaches the house.

    const progress = interpolate(
      frame,
      [0, 179],
      [0, 1],
      {
        easing: Easing.inOut(Easing.ease),
      }
    );

    camera.position.z = 13 - progress * 2.2;
    camera.position.y = 4 - progress * 0.4;

    camera.lookAt(0, 1, 0);

    // Children approach the house.

    kidsRef.current.forEach((kid, index) => {
      kid.position.z =
        5 + index * 0.4 - progress * 2;

      kid.position.y =
        Math.abs(Math.sin(time * 3 + index)) * 0.08;

      kid.rotation.y =
        Math.sin(time * 2 + index) * 0.08;
    });

    renderer.render(scene, camera);

  }, [frame, fps]);

  const titleOpacity = interpolate(
    frame,
    [15, 40, 125, 160],
    [0, 1, 1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#10172b",
      }}
    >
      <canvas
        ref={canvasRef}
        style={{
          width: "100%",
          height: "100%",
        }}
      />

      <div
        style={{
          position: "absolute",
          top: 65,
          width: "100%",
          textAlign: "center",
          color: "#fff1cc",
          fontFamily: "Georgia, serif",
          fontSize: 64,
          fontWeight: "bold",
          letterSpacing: 8,
          opacity: titleOpacity,
          textShadow: "0 4px 20px #ff7b22",
        }}
      >
        HALLOWEEN NIGHT
      </div>

      <div
        style={{
          position: "absolute",
          top: 155,
          width: "100%",
          textAlign: "center",
          color: "#ffffff",
          fontSize: 22,
          letterSpacing: 4,
          opacity: titleOpacity,
        }}
      >
        THE GREAT CANDY CHAOS
      </div>
    </AbsoluteFill>
  );
};