import { useLayoutEffect, useMemo } from "react";
import { useLoader } from "@react-three/fiber";
import { interpolate, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { clone as cloneSkinnedScene } from "three/examples/jsm/utils/SkeletonUtils.js";

export const DobermanModel: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const gltf = useLoader(GLTFLoader, staticFile("models/doberman.glb"));
  const model = useMemo(() => {
    const clone = cloneSkinnedScene(gltf.scene);
    clone.traverse((node) => {
      if ((node as THREE.Mesh).isMesh) {
        node.castShadow = true;
        node.receiveShadow = true;
      }
    });
    return clone;
  }, [gltf.scene]);
  const mixer = useMemo(() => new THREE.AnimationMixer(model), [model]);
  const bones = useMemo(() => {
    const found = new Map<string, THREE.Bone>();
    model.traverse((node) => {
      if ((node as THREE.Bone).isBone) found.set(node.name, node as THREE.Bone);
    });
    return found;
  }, [model]);
  const bindRotations = useMemo(() => {
    return new Map([...bones].map(([name, bone]) => [name, bone.quaternion.clone()]));
  }, [bones]);
  const idleClip = useMemo(
    () => gltf.animations.find((clip) => clip.name === "Idle"),
    [gltf.animations],
  );

  const idleAction = useMemo(() => idleClip ? mixer.clipAction(idleClip) : null, [idleClip, mixer]);

  useLayoutEffect(() => {
    if (!idleAction) return;
    idleAction.setLoop(THREE.LoopRepeat, Infinity);
    idleAction.play();
    return () => {
      idleAction.stop();
    };
  }, [idleAction]);

  useLayoutEffect(() => {
    mixer.setTime(frame / fps);
    const turn = interpolate(frame, [240, 278, 299], [0, 1.0, 1.0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    const head = bones.get("Head");
    const headBase = bindRotations.get("Head");
    if (head && headBase) {
      head.quaternion.copy(headBase).multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), turn));
    }
    const earWiggle = Math.sin(frame * 0.055) * 0.018;
    for (const name of ["Ear_L", "Ear_R"] as const) {
      const ear = bones.get(name);
      const base = bindRotations.get(name);
      if (ear && base) {
        ear.quaternion.copy(base).multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 0, 1), name === "Ear_L" ? earWiggle : -earWiggle));
      }
    }
    model.updateMatrixWorld(true);
  }, [bindRotations, bones, fps, frame, mixer, model]);

  return <primitive object={model} position={[0.22, 0, 0]} />;
};
