import { useMemo } from "react";
import { useCurrentFrame } from "remotion";

const COUNT = 42;

export const DustParticles: React.FC = () => {
  const frame = useCurrentFrame();
  const positions = useMemo(() => {
    const result = new Float32Array(COUNT * 3);
    for (let i = 0; i < COUNT; i++) {
      const a = Math.sin((i + 1) * 127.1) * 43758.5453;
      const b = Math.sin((i + 1) * 269.5) * 19341.743;
      const c = Math.sin((i + 1) * 419.2) * 9871.231;
      result[i * 3] = ((a - Math.floor(a)) * 6.8) - 3.4;
      result[i * 3 + 1] = 0.2 + (b - Math.floor(b)) * 3.1;
      result[i * 3 + 2] = ((c - Math.floor(c)) * 4.2) - 1.5;
    }
    return result;
  }, []);
  const drift = (frame % 600) / 600;

  return (
    <points position={[0, drift * 0.45, -0.8]}>
      <bufferGeometry>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} count={COUNT} itemSize={3} />
      </bufferGeometry>
      <pointsMaterial color="#e8d9c7" size={0.014} sizeAttenuation transparent opacity={0.2} depthWrite={false} />
    </points>
  );
};
