import {makeRoundedRect} from '../geometry/watchGeometry';
import {watchMaterials as M} from '../materials/watchMaterials';
import {CHRONOS_DIMENSIONS} from '../config/productDimensions';

const centerLinkGeometry = makeRoundedRect(0.58, CHRONOS_DIMENSIONS.strapLinkHeight, CHRONOS_DIMENSIONS.strapDepth, 0.075);
const outerLinkGeometry = makeRoundedRect(0.42, CHRONOS_DIMENSIONS.strapLinkHeight, 0.38, 0.065);
const connectorGeometry = makeRoundedRect(1.10, 0.30, 0.48, 0.085);

const HingePin = ({x, y}: {x: number; y: number}) => (
  <mesh name="bracelet-hinge-pin" position={[x, y, 0.22]} rotation={[0, 0, Math.PI / 2]} material={M.screw}>
    <cylinderGeometry args={[0.038, 0.038, 0.23, 16]} />
  </mesh>
);

type LinkProps = {y: number; x: number; z: number; angle: number; index: number; top: boolean};
const ArticulatedLink = ({y, x, z, angle, index, top}: LinkProps) => (
  <group name={`${top ? 'bracelet-top' : 'bracelet-bottom'}-link-${index}`} position={[x, y, z]} rotation={[0, 0, angle]}>
    <mesh geometry={outerLinkGeometry} position={[-0.51, 0, 0]} material={M.brushedMetal} />
    <mesh geometry={centerLinkGeometry} position={[0, 0, 0.035]} material={M.titaniumEdge} />
    <mesh geometry={outerLinkGeometry} position={[0.51, 0, 0]} material={M.brushedMetal} />
    <mesh position={[0, 0, 0.245]} scale={[0.44, 0.105, 0.024]} material={M.screw}>
      <boxGeometry args={[1, 1, 1]} />
    </mesh>
    <HingePin x={-0.55} y={0.0} />
    <HingePin x={0.55} y={0.0} />
  </group>
);

const linkLayout = (top: boolean) => Array.from({length: 7}, (_, i) => {
  const distance = i * 0.38;
  const bend = 0.035 * i + 0.006 * i * i;
  return {
    y: (top ? 2.70 : -2.70) + (top ? distance : -distance),
    x: (top ? -1 : 1) * (0.05 + i * 0.075 + i * i * 0.012),
    z: -0.02 - i * i * 0.025,
    angle: (top ? -1 : 1) * bend,
    index: i,
  };
});

export const WatchBracelet = ({showBack = false, hidden = false}: {showBack?: boolean; hidden?: boolean}) => {
  if (hidden) return null;
  return (
    <group name="bracelet-assembly">
      <group name="bracelet-top-connection" position={[0, 2.37, 0]}>
        <mesh geometry={connectorGeometry} material={M.titaniumEdge} />
        <mesh position={[0, 0, 0.245]} rotation={[0, 0, Math.PI / 2]} material={M.screw}>
          <cylinderGeometry args={[0.07, 0.07, 1.18, 20]} />
        </mesh>
      </group>
      <group name="bracelet-bottom-connection" position={[0, -2.37, 0]}>
        <mesh geometry={connectorGeometry} material={M.titaniumEdge} />
        <mesh position={[0, 0, 0.245]} rotation={[0, 0, Math.PI / 2]} material={M.screw}>
          <cylinderGeometry args={[0.07, 0.07, 1.18, 20]} />
        </mesh>
      </group>
      {linkLayout(true).map((link) => <ArticulatedLink key={`top-${link.index}`} top {...link} />)}
      {linkLayout(false).map((link) => <ArticulatedLink key={`bottom-${link.index}`} top={false} {...link} />)}
      {showBack && <mesh name="bracelet-back-flexure" position={[0, 0, -0.31]} material={M.blackRubber}>
        <boxGeometry args={[1.68, 0.24, 0.04]} />
      </mesh>}
    </group>
  );
};
