import React from "react";
import { Audio } from "@remotion/media";
import { interpolate, staticFile, useCurrentFrame } from "remotion";

type AudioMixProps = {
  voiceoverReady?: boolean;
};

const narrationClips = [
  { name: "Narration · introduction", file: "narration/01-introduction.mp3", from: 0 },
  { name: "Narration · history", file: "narration/02-history.mp3", from: 210 },
  { name: "Narration · ear cropping", file: "narration/03-ear-cropping.mp3", from: 510 },
  { name: "Narration · tail docking", file: "narration/04-tail-docking.mp3", from: 870 },
  { name: "Narration · healing", file: "narration/05-healing.mp3", from: 1140 },
  { name: "Narration · companion life", file: "narration/06-companion-life.mp3", from: 1530 },
  { name: "Narration · closing", file: "narration/07-closing.mp3", from: 1860 },
];

const dialogueClips = [
  { name: "Dialogue · child", file: "dialogue/01-child.mp3", from: 1764 },
  { name: "Dialogue · guardian", file: "dialogue/02-guardian.mp3", from: 1815 },
];

export const DobermanAudio: React.FC<AudioMixProps> = ({ voiceoverReady = false }) => {
  const frame = useCurrentFrame();

  // Duck the original score smoothly while narration or dialogue is speaking.
  const speechWindows = [
    [0, 150],
    [210, 455],
    [510, 755],
    [870, 1055],
    [1140, 1385],
    [1530, 1750],
    [1860, 2050],
  ];
  const dialogueWindows = [
    [1764, 1812],
    [1815, 1850],
  ];
  const duck = [...speechWindows, ...dialogueWindows].reduce((level, [start, end]) => {
    const envelope = interpolate(
      frame,
      [start - 18, start + 8, end - 8, end + 18],
      [1, 0.42, 0.42, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
    );
    return Math.min(level, envelope);
  }, 1);

  const fadeIn = interpolate(frame, [0, 36], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const fadeOut = interpolate(frame, [2010, 2100], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const scoreVolume = 0.34 * fadeIn * fadeOut * duck;
  const effectsVolume = 0.62 * fadeIn * fadeOut;

  return (
    <>
      <Audio
        name="Music · original warm cinematic bed"
        src={staticFile("audio/doberman-score.wav")}
        volume={scoreVolume}
      />
      <Audio
        name="Sound effects · chimes, transitions, recovery, ball"
        src={staticFile("audio/doberman-effects.wav")}
        volume={effectsVolume}
      />
      {voiceoverReady && narrationClips.map((clip) => (
        <Audio
          key={clip.file}
          name={clip.name}
          src={staticFile(`audio/${clip.file}`)}
          from={clip.from}
          volume={1}
        />
      ))}
      {voiceoverReady && dialogueClips.map((clip) => (
        <Audio
          key={clip.file}
          name={clip.name}
          src={staticFile(`audio/${clip.file}`)}
          from={clip.from}
          volume={1}
        />
      ))}
    </>
  );
};
