import React from "react";
import { ThreeCanvas } from "@remotion/three";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { DobermanAudio } from "./DobermanAudio";

const FPS = 30;
const TOTAL_FRAMES = 70 * FPS;

const chapters = [
  {
    start: 0,
    end: 7 * FPS,
    number: "01",
    title: "MEET THE DOBERMAN",
    line: "This is a Doberman—with the ears and tail it was born with.",
    color: "#f5aa64",
  },
  {
    start: 7 * FPS,
    end: 17 * FPS,
    number: "02",
    title: "A WORKING-DOG PAST",
    line: "Dobermans were developed for protection work. People believed shorter ears and tails meant less for an attacker to grab, and less chance of injury.",
    color: "#e9a970",
  },
  {
    start: 17 * FPS,
    end: 29 * FPS,
    number: "03",
    title: "EAR CROPPING",
    line: "Ear cropping removes part of the ear. Afterward, ears may be taped or posted upright as they heal.",
    color: "#eb9c84",
  },
  {
    start: 29 * FPS,
    end: 38 * FPS,
    number: "04",
    title: "TAIL DOCKING",
    line: "Tail docking shortens the tail. Preventing injury was one reason people gave—but it doesn’t make it necessary for every dog.",
    color: "#e7a179",
  },
  {
    start: 38 * FPS,
    end: 51 * FPS,
    number: "05",
    title: "HEALING TAKES TIME",
    line: "Both procedures can be painful. Even with anesthesia, recovery and healing can take weeks.",
    color: "#e9b47f",
  },
  {
    start: 51 * FPS,
    end: 62 * FPS,
    number: "06",
    title: "LIFE AS A COMPANION",
    line: "For a pet with no medical need, these changes are often about appearance.",
    color: "#91c8a8",
  },
  {
    start: 62 * FPS,
    end: TOTAL_FRAMES,
    number: "07",
    title: "LET THEM BE THEMSELVES",
    line: "Their ears and tails help them communicate. Let them be dogs, just as they are.",
    color: "#f0bd6e",
  },
];

const Dog: React.FC<{ frame: number }> = ({ frame }) => {
  const walk = frame > 1500 && frame < 1840;
  const run = walk ? Math.sin(frame * 0.17) : Math.sin(frame * 0.045);
  const entrance = interpolate(frame, [0, 70, 170], [-1.5, -0.35, 0], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const resting = frame >= 1140 && frame < 1530;
  const dogY = resting ? -0.1 : 0;
  const earTilt = frame >= 1860 ? 0.04 * Math.sin(frame * 0.12) : 0;

  return (
    <group position={[entrance, dogY, 0]} rotation={[0, frame > 1530 && frame < 1860 ? 0.2 : 0, 0]}>
      {/* Warm black-and-rust coat, with natural floppy ears and a full wagging tail. */}
      <mesh position={[0, 1.18, 0]} scale={[0.56, 0.7, 0.93]} castShadow>
        <sphereGeometry args={[1, 32, 24]} />
        <meshStandardMaterial color="#25252a" roughness={0.68} />
      </mesh>
      <mesh position={[0, 1.54, 0.03]} scale={[0.34, 0.22, 0.64]}>
        <sphereGeometry args={[1, 24, 18]} />
        <meshStandardMaterial color="#9e5638" roughness={0.75} />
      </mesh>

      {/* Neck and proud, gentle head. */}
      <mesh position={[0, 1.69, 0.47]} rotation={[-0.25, 0, 0]} scale={[0.35, 0.53, 0.36]}>
        <sphereGeometry args={[1, 28, 22]} />
        <meshStandardMaterial color="#29292e" roughness={0.7} />
      </mesh>
      <group position={[0, 2.18, 0.62]} rotation={[0, 0, 0.025 * Math.sin(frame * 0.035)]}>
        <mesh scale={[0.46, 0.49, 0.43]} castShadow>
          <sphereGeometry args={[1, 32, 28]} />
          <meshStandardMaterial color="#242429" roughness={0.66} />
        </mesh>
        <mesh position={[0, -0.19, 0.33]} scale={[0.3, 0.2, 0.34]}>
          <sphereGeometry args={[1, 24, 18]} />
          <meshStandardMaterial color="#a35c3b" roughness={0.72} />
        </mesh>
        <mesh position={[0, -0.16, 0.59]} scale={[0.13, 0.1, 0.11]}>
          <sphereGeometry args={[1, 20, 14]} />
          <meshStandardMaterial color="#17171b" roughness={0.35} />
        </mesh>
        {[-1, 1].map((side) => (
          <React.Fragment key={side}>
            <mesh position={[side * 0.19, 0.06, 0.33]} scale={[0.055, 0.065, 0.035]}>
              <sphereGeometry args={[1, 16, 12]} />
              <meshStandardMaterial color="#fff1d6" />
            </mesh>
            <mesh position={[side * 0.19, 0.06, 0.36]} scale={[0.027, 0.037, 0.02]}>
              <sphereGeometry args={[1, 12, 10]} />
              <meshStandardMaterial color="#17171b" />
            </mesh>
            {/* Natural ear shape stays visible in every shot. */}
            <mesh
              position={[side * 0.37, -0.19, 0.02]}
              rotation={[0.05, side * -0.14, side * (0.58 + earTilt)]}
              scale={[0.16, 0.35, 0.09]}
              castShadow
            >
              <sphereGeometry args={[1, 22, 18]} />
              <meshStandardMaterial color="#302a2c" roughness={0.76} />
            </mesh>
            <mesh position={[side * 0.22, -0.2, 0.27]} scale={[0.085, 0.13, 0.065]}>
              <sphereGeometry args={[1, 20, 14]} />
              <meshStandardMaterial color="#a65b39" roughness={0.8} />
            </mesh>
          </React.Fragment>
        ))}
      </group>

      {/* Four legs: a calm stance, a resting beat, then a playful trot. */}
      {[-1, 1].map((side) =>
        [-1, 1].map((front) => (
          <group
            key={`${side}-${front}`}
            position={[side * 0.35, 0.78, front * 0.53]}
            rotation={[walk ? run * 0.5 * (front === 1 ? 1 : -1) : 0, 0, 0]}
          >
            <mesh position={[0, -0.34, 0]} scale={[0.15, 0.48, 0.17]} castShadow>
              <capsuleGeometry args={[0.13, 0.46, 6, 12]} />
              <meshStandardMaterial color="#242429" roughness={0.7} />
            </mesh>
            <mesh position={[0, -0.19, 0.04]} scale={[0.145, 0.27, 0.18]}>
              <sphereGeometry args={[1, 18, 14]} />
              <meshStandardMaterial color={front === 1 ? "#aa6040" : "#242429"} roughness={0.75} />
            </mesh>
            <mesh position={[0, -0.72, 0.07]} scale={[0.18, 0.09, 0.25]}>
              <sphereGeometry args={[1, 18, 14]} />
              <meshStandardMaterial color="#19191e" roughness={0.7} />
            </mesh>
          </group>
        )),
      )}

      {/* Full tail: an important expressive part of the character. */}
      <group
        position={[0, 1.41, -0.78]}
        rotation={[0.34 + Math.sin(frame * (walk ? 0.16 : 0.11)) * (walk ? 0.46 : 0.2), 0, Math.sin(frame * 0.1) * 0.24]}
      >
        <mesh position={[0, 0.25, -0.12]} rotation={[0.2, 0, 0]} scale={[0.105, 0.44, 0.11]}>
          <capsuleGeometry args={[0.095, 0.47, 6, 12]} />
          <meshStandardMaterial color="#25252a" roughness={0.68} />
        </mesh>
      </group>

      <mesh position={[0, 0.99, 0.53]} rotation={[Math.PI / 2, 0, 0]}>
        <torusGeometry args={[0.36, 0.055, 10, 48]} />
        <meshStandardMaterial color="#cb9a50" metalness={0.45} roughness={0.36} />
      </mesh>
    </group>
  );
};

const EarIllustration: React.FC<{ frame: number }> = ({ frame }) => {
  const progress = interpolate(frame, [510, 560, 820, 870], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return (
    <group position={[2.2, 1.95, -0.3]} scale={[progress, progress, progress]}>
      <mesh position={[0, 0, -0.13]}>
        <boxGeometry args={[2.35, 2.05, 0.18]} />
        <meshStandardMaterial color="#2d3544" roughness={0.9} />
      </mesh>
      <mesh position={[-0.55, 0.08, 0.06]} rotation={[0, 0, -0.52]} scale={[0.24, 0.48, 0.08]}>
        <sphereGeometry args={[1, 20, 16]} />
        <meshStandardMaterial color="#bd795d" />
      </mesh>
      <mesh position={[0.55, 0.08, 0.06]} rotation={[0, 0, 0.15]} scale={[0.2, 0.53, 0.08]}>
        <sphereGeometry args={[1, 20, 16]} />
        <meshStandardMaterial color="#bd795d" />
      </mesh>
      {/* Dotted guide explains the change without depicting an incision. */}
      {Array.from({ length: 5 }, (_, i) => (
        <mesh key={i} position={[0.55, -0.26 + i * 0.12, 0.16]}>
          <sphereGeometry args={[0.035, 10, 8]} />
          <meshBasicMaterial color="#f2bf77" />
        </mesh>
      ))}
      <mesh position={[0, -0.63, 0.12]}>
        <sphereGeometry args={[0.13, 16, 12]} />
        <meshStandardMaterial color="#e3b65f" emissive="#6a3c14" />
      </mesh>
    </group>
  );
};

const TailIllustration: React.FC<{ frame: number }> = ({ frame }) => {
  const progress = interpolate(frame, [870, 920, 1090, 1140], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return (
    <group position={[2.25, 1.88, -0.3]} scale={[progress, progress, progress]}>
      <mesh position={[0, 0, -0.13]}>
        <boxGeometry args={[2.25, 1.8, 0.18]} />
        <meshStandardMaterial color="#2d3544" roughness={0.9} />
      </mesh>
      <mesh position={[-0.45, 0.2, 0.04]} scale={[0.55, 0.42, 0.22]}>
        <sphereGeometry args={[1, 20, 16]} />
        <meshStandardMaterial color="#33333a" />
      </mesh>
      <mesh position={[0.05, 0.2, 0.04]} rotation={[0, 0, -0.35]} scale={[0.22, 0.38, 0.19]}>
        <sphereGeometry args={[1, 18, 14]} />
        <meshStandardMaterial color="#a65c3c" />
      </mesh>
      <mesh position={[0.68, 0.18, 0.03]} rotation={[0, 0, 0.52]} scale={[0.08, 0.32, 0.08]}>
        <capsuleGeometry args={[0.08, 0.3, 4, 8]} />
        <meshStandardMaterial color="#33333a" />
      </mesh>
      <mesh position={[0.61, -0.48, 0.1]}>
        <sphereGeometry args={[0.11, 14, 10]} />
        <meshStandardMaterial color="#e3b65f" emissive="#6a3c14" />
      </mesh>
    </group>
  );
};

const HealingCalendar: React.FC<{ frame: number }> = ({ frame }) => {
  const progress = interpolate(frame, [1140, 1190, 1490, 1530], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const pages = interpolate(frame, [1160, 1480], [1, 6], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return (
    <group position={[2.15, 1.85, -0.3]} scale={[progress, progress, progress]}>
      <mesh position={[0, 0, -0.14]}>
        <boxGeometry args={[2.1, 1.85, 0.2]} />
        <meshStandardMaterial color="#33404d" roughness={0.88} />
      </mesh>
      <mesh position={[0, 0.35, 0.01]}>
        <boxGeometry args={[1.45, 0.44, 0.06]} />
        <meshStandardMaterial color="#d69a5a" />
      </mesh>
      {Array.from({ length: 6 }, (_, i) => (
        <mesh key={i} position={[-0.5 + (i % 3) * 0.5, -0.12 - Math.floor(i / 3) * 0.42, 0.03]}>
          <boxGeometry args={[0.35, 0.25, 0.06]} />
          <meshStandardMaterial color={i < pages ? "#e6c895" : "#66727a"} />
        </mesh>
      ))}
      <mesh position={[0.66, 0.37, 0.08]}>
        <sphereGeometry args={[0.13, 16, 12]} />
        <meshStandardMaterial color="#bb6e57" />
      </mesh>
    </group>
  );
};

const PlayBall: React.FC<{ frame: number }> = ({ frame }) => {
  const visible = interpolate(frame, [1530, 1580, 1810, 1860], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return (
    <group position={[1.65 + Math.sin(frame * 0.055) * 0.28, 0.3, 0.7]} scale={visible}>
      <mesh castShadow>
        <sphereGeometry args={[0.35, 28, 20]} />
        <meshStandardMaterial color="#f1b84f" roughness={0.42} />
      </mesh>
      <mesh rotation={[0.4, 0.5, 0.2]}>
        <torusGeometry args={[0.23, 0.025, 8, 36]} />
        <meshStandardMaterial color="#fff0c8" />
      </mesh>
    </group>
  );
};

const Set: React.FC<{ frame: number }> = ({ frame }) => {
  const { width, height } = useVideoConfig();
  const companion = frame >= 1530 && frame < 1860;
  const warm = frame >= 1860;
  const cameraX = interpolate(frame, [0, 210, 510, 870, 1140, 1530, 1860, 2100], [0, 0.25, -0.45, -0.4, 0.45, 0.1, 0, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const cameraY = interpolate(frame, [0, 210, 510, 870, 1140, 1530, 1860, 2100], [2.8, 2.5, 2.3, 2.4, 2.8, 2.45, 2.6, 2.55], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <ThreeCanvas
      width={width}
      height={height}
      camera={{ position: [cameraX, cameraY, 9.2], fov: 36 }}
      shadows
    >
      <color attach="background" args={[warm ? "#25343a" : "#202a37"]} />
      <ambientLight intensity={1.5} color="#cbd6e2" />
      <directionalLight position={[-4, 8, 5]} intensity={3.2} color={warm ? "#ffd7a0" : "#d5e2ff"} castShadow />
      <pointLight position={[3, 4, 3]} intensity={companion ? 95 : 62} color={companion ? "#ffc77d" : "#f0a46c"} />
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.04, 0]} receiveShadow>
        <planeGeometry args={[200, 200]} />
        <meshStandardMaterial color={warm ? "#4a625d" : "#303744"} roughness={0.96} />
      </mesh>
      <mesh position={[0, 2, -3.5]}>
        <boxGeometry args={[14, 5, 0.3]} />
        <meshStandardMaterial color={warm ? "#435759" : "#343b4a"} roughness={0.92} />
      </mesh>
      <mesh position={[-4.2, 1.65, -3.25]}>
        <boxGeometry args={[1.3, 1.9, 0.08]} />
        <meshStandardMaterial color="#f2bc78" emissive="#684421" />
      </mesh>
      <mesh position={[4.1, 1.65, -3.25]}>
        <boxGeometry args={[1.3, 1.9, 0.08]} />
        <meshStandardMaterial color="#f2bc78" emissive="#684421" />
      </mesh>
      {/* Subtle old-work silhouette, present only during the historical beat. */}
      <mesh position={[-2.55, 1.36, -0.9]} scale={[0.45, 1.35, 0.2]}>
        <capsuleGeometry args={[0.4, 1.45, 6, 12]} />
        <meshStandardMaterial color="#68707b" transparent opacity={frame >= 210 && frame < 510 ? 0.38 : 0} />
      </mesh>
      <Dog frame={frame} />
      <EarIllustration frame={frame} />
      <TailIllustration frame={frame} />
      <HealingCalendar frame={frame} />
      <PlayBall frame={frame} />
      {/* A small childlike silhouette joins for the companion-life beat. */}
      {companion && (
        <group position={[2.15, 0, 0.2]}>
          <mesh position={[0, 1.2, 0]}>
            <capsuleGeometry args={[0.24, 0.78, 5, 10]} />
            <meshStandardMaterial color="#9bc1c8" />
          </mesh>
          <mesh position={[0, 1.94, 0.02]}>
            <sphereGeometry args={[0.29, 20, 16]} />
            <meshStandardMaterial color="#dfa781" />
          </mesh>
          <mesh position={[0.12, 0.58, 0.02]} rotation={[0, 0, -0.55]}>
            <capsuleGeometry args={[0.075, 0.45, 4, 8]} />
            <meshStandardMaterial color="#9bc1c8" />
          </mesh>
        </group>
      )}
      <mesh position={[0, 0.012, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <circleGeometry args={[4.1, 64]} />
        <meshBasicMaterial color={warm ? "#b38a52" : "#7788a6"} transparent opacity={0.09} />
      </mesh>
    </ThreeCanvas>
  );
};

const StoryText: React.FC = () => {
  const frame = useCurrentFrame();
  const chapter = chapters.find((item) => frame >= item.start && frame < item.end) ?? chapters[0];
  const localFrame = frame - chapter.start;
  const fade = interpolate(localFrame, [0, 12, chapter.end - chapter.start - 16, chapter.end - chapter.start], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const lift = interpolate(localFrame, [0, 18], [18, 0], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const closing = frame >= 1860;

  return (
    <AbsoluteFill style={{ fontFamily: "Arial, sans-serif", pointerEvents: "none" }}>
      <div
        style={{
          position: "absolute",
          top: 35,
          left: 48,
          display: "flex",
          alignItems: "center",
          gap: 12,
          color: "#f8ead7",
          fontSize: 14,
          fontWeight: 800,
          letterSpacing: 3,
          textShadow: "0 2px 12px #0009",
        }}
      >
        <span style={{ color: chapter.color }}>{chapter.number}</span>
        <span>{chapter.title}</span>
      </div>
      <div
        style={{
          position: "absolute",
          left: 56,
          right: 56,
          bottom: 42,
          padding: "19px 25px 21px",
          borderLeft: `4px solid ${chapter.color}`,
          borderRadius: 10,
          background: "linear-gradient(90deg, #141923e8, #141923c9 76%, #14192300)",
          color: "#fff7e9",
          fontSize: 26,
          fontWeight: 600,
          lineHeight: 1.28,
          letterSpacing: 0.1,
          opacity: chapter.number === "06"
            ? interpolate(localFrame, [0, 12, 210, 235], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
            : fade,
          translate: `0 ${lift}px`,
          textShadow: "0 2px 8px #0008",
        }}
      >
        {chapter.line}
      </div>
      {frame >= 1764 && frame < 1860 && (
        <div
          style={{
            position: "absolute",
            left: 56,
            bottom: 42,
            maxWidth: 700,
            padding: "17px 22px",
            borderRadius: 12,
            background: "#243440ed",
            color: "#fff7e9",
            fontSize: 25,
            fontWeight: 700,
            opacity: interpolate(frame, [1764, 1776, 1840, 1855], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
          }}
        >
          {frame < 1815 ? "CHILD: He looks happy just like that." : "GUARDIAN: He is."}
        </div>
      )}
      {closing && (
        <div
          style={{
            position: "absolute",
            top: 106,
            left: 56,
            color: "#ffcf8c",
            fontSize: 48,
            fontWeight: 900,
            letterSpacing: 1,
            textShadow: "0 4px 24px #0009",
            opacity: interpolate(frame, [1860, 1890], [0, 1], { extrapolateRight: "clamp" }),
          }}
        >
          LET THEM BE THEMSELVES.
        </div>
      )}
    </AbsoluteFill>
  );
};

export const DobermanStory: React.FC<{ voiceoverReady?: boolean }> = ({ voiceoverReady = false }) => {
  const frame = useCurrentFrame();
  const fade = interpolate(frame, [0, 18, TOTAL_FRAMES - 24, TOTAL_FRAMES], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const vignette = frame < 7 * FPS || frame >= 1860;

  return (
    <AbsoluteFill style={{ backgroundColor: "#202a37" }}>
      <Set frame={frame} />
      <StoryText />
      <DobermanAudio voiceoverReady={voiceoverReady} />
      <AbsoluteFill
        style={{
          opacity: fade,
          background: vignette
            ? "radial-gradient(ellipse at center, transparent 44%, #11172280 100%)"
            : "linear-gradient(180deg, #11172242 0%, transparent 28%, transparent 68%, #11172255 100%)",
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

