import {useVideoConfig} from 'remotion';
import {ThreeCanvas} from '@remotion/three';
import {Environment, Lightformer} from '@react-three/drei';
import * as THREE from 'three';
import {ChronosWatch} from '../components/ChronosWatch';
import type {ChronosView} from '../config/productDimensions';

const Backdrop = () => (
  <mesh position={[0, 0, -5]}>
    <planeGeometry args={[30, 30]} />
    <shaderMaterial
      vertexShader={`varying vec2 vUv; void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`}
      fragmentShader={`varying vec2 vUv; void main(){float g=1.0-distance(vUv,vec2(.50,.55));vec3 c=mix(vec3(.002,.005,.012),vec3(.015,.05,.095),clamp(g,0.,1.));gl_FragColor=vec4(c,1.);}`}
    />
  </mesh>
);

const Lighting = ({boost = 1}: {boost?: number}) => (
  <>
    <ambientLight intensity={0.12 * boost} color="#6f9dc3" />
    <ambientLight intensity={0.18 * boost} color="#87a9c2" />
    <directionalLight position={[-5, 7, 8]} intensity={1.85 * boost} color="#e3f4ff" />
    <directionalLight position={[6, 2, 4]} intensity={1.25 * boost} color="#70b8ff" />
    <directionalLight position={[-8, 1, 4]} intensity={0.85 * boost} color="#9fb6c5" />
    <directionalLight position={[0, 0, 8]} intensity={0.22 * boost} color="#d5e8f5" />
    <pointLight position={[0, 0, 4]} intensity={0.05 * boost} distance={12} color="#64b7ff" />
    <rectAreaLight position={[-3.5, 4.0, 5.0]} rotation={[-0.35, -0.3, -0.15]} width={5.5} height={2.8} intensity={2.3 * boost} color="#e8f5ff" />
    <rectAreaLight position={[4.5, 0.5, 2.5]} rotation={[0.1, 1.0, 0.2]} width={2.4} height={5.5} intensity={1.6 * boost} color="#69b8ff" />
    <Environment resolution={128} frames={1}>
      <Lightformer position={[-4, 4, 4]} scale={[4, 2, 1]} intensity={2.5 * boost} color="#cfefff" />
      <Lightformer position={[4, 0, 1]} scale={[2, 5, 1]} intensity={2.0 * boost} color="#4d8fff" />
      <Lightformer position={[0, -5, 3]} scale={[3, 2, 1]} intensity={0.8 * boost} color="#527caa" />
    </Environment>
  </>
);

export const ChronosPreview = ({view = 'front'}: {view?: ChronosView}) => {
  const {width, height} = useVideoConfig();
  const isExploded = view === 'exploded';
  const isThreeQuarter = view === 'three-quarter';
  const isSide = view === 'side';
  const isBack = view === 'back';
  const cameraPosition: [number, number, number] = isExploded
    ? [6.0, 4.5, 24.5]
    : isThreeQuarter
      ? [5.2, 2.8, 13.8]
      : isSide
        ? [10.8, 3.2, 17.0]
        : [0.9, 2.0, 18.4];
  const groupRotation: [number, number, number] = isExploded
    ? [0.12, -0.25, 0.02]
    : isThreeQuarter
      ? [0.04, -0.17, 0.02]
      : isSide
        ? [0.03, -0.12, 0.02]
      : [0.01, -0.03, 0.005];
  return (
    <div style={{width: '100%', height: '100%', background: '#020611'}}>
      <ThreeCanvas
        width={width}
        height={height}
        camera={{position: cameraPosition, fov: isExploded ? 44 : isThreeQuarter ? 38 : isSide ? 40 : 39, near: 0.1, far: 100}}
        gl={{antialias: true, alpha: false, preserveDrawingBuffer: true, toneMapping: THREE.ACESFilmicToneMapping, toneMappingExposure: 1.08}}
        onCreated={({camera, gl}) => {
          camera.lookAt(0, isExploded ? 0.15 : 0.0, 0);
          camera.updateProjectionMatrix();
          gl.setClearColor('#020611');
        }}
      >
        <Backdrop />
        <Lighting boost={isExploded ? 1.65 : isBack ? 1.35 : 1} />
        <group position={[0, isExploded ? 0 : -0.15, 0]} rotation={groupRotation} scale={isExploded ? 1 : 1}>
          <ChronosWatch view={view} />
        </group>
      </ThreeCanvas>
    </div>
  );
};
