import {AbsoluteFill, Img, staticFile} from "remotion";

/**
 * The reference artwork is intentionally rendered at its native dimensions.
 * Keeping the source PNG unchanged is what preserves its exact pixels,
 * orientation, and color values.
 */
export const FlowerReference: React.FC = () => {
  return (
    <AbsoluteFill style={{backgroundColor: "#000000"}}>
      <Img
        src={staticFile("flower-reference.png")}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: 780,
          height: 768,
          display: "block",
          objectFit: "fill",
        }}
      />
    </AbsoluteFill>
  );
};
