import {AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame} from "remotion";
import type {CSSProperties} from "react";

const SOURCE_WIDTH = 780;
const SOURCE_HEIGHT = 768;
const FOCUS_X = 285;
const FOCUS_Y = 190;
const FRAME_COUNT = 480;

type PetalLayer = {
  readonly clipPath: string;
  readonly closedTranslate: readonly [number, number];
  readonly closedRotate: number;
  readonly closedScale: readonly [number, number];
  readonly startFrame: number;
  readonly endFrame: number;
};

const PETAL_LAYERS: readonly PetalLayer[] = [
  {
    clipPath:
      "polygon(29% 10%, 35% 8%, 41% 9%, 44% 15%, 45% 26%, 43% 34%, 39% 40%, 31% 40%, 28% 34%, 28% 22%)",
    closedTranslate: [8, 10],
    closedRotate: 0,
    closedScale: [0.56, 0.92],
    startFrame: 240,
    endFrame: 330,
  },
  {
    clipPath:
      "polygon(18% 9%, 23% 10%, 25% 18%, 27% 28%, 33% 36%, 26% 33%, 20% 27%, 17% 20%, 15% 13%)",
    closedTranslate: [76, 8],
    closedRotate: 16,
    closedScale: [0.5, 0.9],
    startFrame: 168,
    endFrame: 270,
  },
  {
    clipPath:
      "polygon(45% 8%, 50% 9%, 53% 16%, 52% 27%, 47% 35%, 43% 35%, 45% 25%, 47% 16%)",
    closedTranslate: [-62, 10],
    closedRotate: -16,
    closedScale: [0.5, 0.9],
    startFrame: 168,
    endFrame: 270,
  },
  {
    clipPath:
      "polygon(18% 15%, 26% 15%, 34% 27%, 36% 35%, 31% 38%, 23% 34%, 18% 28%, 15% 21%)",
    closedTranslate: [58, 25],
    closedRotate: 21,
    closedScale: [0.43, 0.78],
    startFrame: 204,
    endFrame: 320,
  },
  {
    clipPath:
      "polygon(41% 16%, 49% 15%, 56% 17%, 58% 23%, 55% 30%, 49% 36%, 42% 38%, 40% 33%)",
    closedTranslate: [-55, 25],
    closedRotate: -21,
    closedScale: [0.43, 0.78],
    startFrame: 204,
    endFrame: 320,
  },
];

const easeInOut = Easing.bezier(0.22, 0.8, 0.24, 1);
const openEase = Easing.bezier(0.16, 1, 0.3, 1);

const imageStyle: CSSProperties = {
  position: "absolute",
  top: 0,
  left: 0,
  width: SOURCE_WIDTH,
  height: SOURCE_HEIGHT,
  display: "block",
  objectFit: "fill",
  pointerEvents: "none",
};

const sourceImage = staticFile("flower-reference.png");
const petalImage = staticFile("flower-petal-matte.png");
const budImage = staticFile("flower-bud-matte.png");

const SourceLayer: React.FC<{
  readonly clipPath?: string;
  readonly opacity?: number;
  readonly src?: string;
  readonly transform?: string;
}> = ({clipPath, opacity = 1, src = sourceImage, transform}) => (
  <Img
    src={src}
    style={{
      ...imageStyle,
      clipPath,
      opacity,
      transform,
      transformOrigin: `${FOCUS_X}px 220px`,
    }}
  />
);

const PetalLayers: React.FC<{readonly frame: number; readonly opacity: number}> = ({
  frame,
  opacity,
}) => (
  <>
    {PETAL_LAYERS.map((petal, index) => {
      const progress = interpolate(
        frame,
        [petal.startFrame, petal.endFrame],
        [0, 1],
        {
          easing: openEase,
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        },
      );
      const translateX = interpolate(progress, [0, 1], [petal.closedTranslate[0], 0]);
      const translateY = interpolate(progress, [0, 1], [petal.closedTranslate[1], 0]);
      const rotate = interpolate(progress, [0, 1], [petal.closedRotate, 0]);
      const scaleX = interpolate(progress, [0, 1], [petal.closedScale[0], 1]);
      const scaleY = interpolate(progress, [0, 1], [petal.closedScale[1], 1]);

      return (
        <SourceLayer
          key={index}
          clipPath={petal.clipPath}
          src={petalImage}
          opacity={opacity * progress}
          transform={`translate(${translateX}px, ${translateY}px) rotate(${rotate}deg) scale(${scaleX}, ${scaleY})`}
        />
      );
    })}
  </>
);

const ClosedBud: React.FC<{readonly opacity: number}> = ({opacity}) => (
  <SourceLayer
    src={budImage}
    opacity={opacity}
    transform="translate(0px, 8px) scale(0.78, 1.08)"
  />
);

const MacroDetails: React.FC<{readonly frame: number; readonly opacity: number}> = ({
  frame,
  opacity,
}) => {
  const drift = interpolate(frame, [360, FRAME_COUNT - 1], [0, -24], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.linear,
  });
  const stamenOpacity = opacity * 0.82;
  const pollen = [
    {x: 274, y: 178, dx: 9, phase: 0.3},
    {x: 286, y: 170, dx: -12, phase: 1.5},
    {x: 295, y: 184, dx: 15, phase: 2.4},
    {x: 267, y: 188, dx: -8, phase: 3.6},
    {x: 302, y: 172, dx: 6, phase: 4.8},
  ];

  return (
    <svg
      aria-hidden="true"
      viewBox={`0 0 ${SOURCE_WIDTH} ${SOURCE_HEIGHT}`}
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: SOURCE_WIDTH,
        height: SOURCE_HEIGHT,
        opacity,
        pointerEvents: "none",
        overflow: "visible",
      }}
    >
      <g fill="none" stroke="#e7b95c" strokeLinecap="round" strokeWidth="1.25" opacity={stamenOpacity}>
        <path d="M285 200 C278 188 268 179 257 170" />
        <path d="M286 201 C286 184 284 172 280 160" />
        <path d="M288 201 C295 185 302 175 312 168" />
        <path d="M283 202 C270 194 258 190 247 189" />
        <path d="M290 202 C305 197 317 192 326 184" />
        <path d="M284 201 C278 190 273 182 270 171" />
      </g>
      <g fill="#f0c866" opacity={stamenOpacity}>
        <ellipse cx="256" cy="169" rx="3" ry="2" />
        <ellipse cx="280" cy="159" rx="3" ry="2" />
        <ellipse cx="312" cy="167" rx="3" ry="2" />
        <ellipse cx="247" cy="189" rx="3" ry="2" />
        <ellipse cx="326" cy="184" rx="3" ry="2" />
        <ellipse cx="270" cy="170" rx="3" ry="2" />
      </g>
      <g fill="#f4d479" opacity={opacity * 0.72}>
        {pollen.map((grain) => (
          <circle
            key={`${grain.x}-${grain.y}`}
            cx={grain.x + grain.dx * (frame - 360) / 120 + Math.sin(frame * 0.025 + grain.phase) * 1.5}
            cy={grain.y + drift + Math.cos(frame * 0.02 + grain.phase) * 1.2}
            r="1.8"
          />
        ))}
      </g>
      <g
        fill="none"
        stroke="#f7dfe2"
        strokeLinecap="round"
        strokeWidth="0.9"
        opacity={opacity * 0.22}
      >
        <path d={`M268 205 C254 188 269 170 258 ${150 + drift * 0.35}`} />
        <path d={`M300 207 C316 190 302 174 314 ${151 + drift * 0.3}`} />
      </g>
      <g
        fill="none"
        stroke="#eef8ef"
        strokeLinecap="round"
        strokeWidth="1.2"
        opacity={opacity * 0.42}
      >
        <path d={`M255 208 C232 189 251 160 238 ${126 + drift * 0.28}`} />
        <path d={`M315 210 C338 190 321 158 337 ${122 + drift * 0.24}`} />
        <path d={`M286 206 C272 182 290 151 282 ${116 + drift * 0.2}`} />
      </g>
    </svg>
  );
};

export const FlowerBloom: React.FC = () => {
  const frame = useCurrentFrame();

  const cameraScale = interpolate(frame, [0, 168, 336, FRAME_COUNT - 1], [1.2, 1.38, 1.52, 3.25], {
    easing: easeInOut,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const focusY = interpolate(frame, [0, 168, 336, FRAME_COUNT - 1], [2150, 1020, 990, 960], {
    easing: easeInOut,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const artLeft = 540 - FOCUS_X;
  const artTop = focusY - FOCUS_Y;
  const cameraTilt = interpolate(frame, [0, 168, 336, 430, FRAME_COUNT - 1], [0, 0, 0, 32, 32], {
    easing: easeInOut,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const bloomProgress = interpolate(frame, [168, 300], [0, 1], {
    easing: easeInOut,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const apertureRadiusX = interpolate(bloomProgress, [0, 1], [8, 34]);
  const apertureRadiusY = interpolate(bloomProgress, [0, 1], [14, 30]);
  const bloomClipPath = `ellipse(${apertureRadiusX}% ${apertureRadiusY}% at 36.5% 21%)`;
  const closedBudOpacity = interpolate(frame, [0, 168, 260], [1, 1, 0], {
    easing: easeInOut,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const macroReveal = interpolate(frame, [360, 430], [0, 1], {
    easing: openEase,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const sepalProgress = interpolate(frame, [168, 350], [0, 1], {
    easing: openEase,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const sepalTranslateX = interpolate(sepalProgress, [0, 1], [12, 0]);
  const sepalRotate = interpolate(sepalProgress, [0, 1], [2, 0]);
  const sepalScaleX = interpolate(sepalProgress, [0, 1], [0.82, 1]);

  return (
    <AbsoluteFill style={{backgroundColor: "#000000", overflow: "hidden"}}>
      <div
        style={{
          position: "absolute",
          left: artLeft,
          top: artTop,
          width: SOURCE_WIDTH,
          height: SOURCE_HEIGHT,
          transform: `perspective(1500px) rotateX(${cameraTilt}deg) scale(${cameraScale})`,
          transformOrigin: `${FOCUS_X}px ${FOCUS_Y}px`,
          pointerEvents: "none",
        }}
      >
        <SourceLayer clipPath="inset(34% 0 0 0)" />
        <SourceLayer
          clipPath="inset(34% 0 50% 0)"
          opacity={sepalProgress}
          transform={`translate(${sepalTranslateX}px, 0px) rotate(${sepalRotate}deg) scale(${sepalScaleX}, 1)`}
        />
        <ClosedBud opacity={closedBudOpacity} />
        <SourceLayer clipPath={bloomClipPath} opacity={bloomProgress} />
        <PetalLayers frame={frame} opacity={0.18 * (1 - bloomProgress)} />
        <MacroDetails frame={frame} opacity={macroReveal} />
      </div>
    </AbsoluteFill>
  );
};
