type RotationSegment = {
  readonly kind: "burst" | "hold";
  readonly duration: number;
  readonly angle?: number;
};

type MotionSpec = {
  readonly direction: 1 | -1;
  readonly offset: number;
  readonly segments: readonly RotationSegment[];
};

type Vec3 = [number, number, number];

const WORLD_WIDTH = 21;
const WORLD_HEIGHT = 10;
const REFERENCE_WIDTH = 1623;
const REFERENCE_HEIGHT = 768;
const PX_TO_WORLD_X = WORLD_WIDTH / REFERENCE_WIDTH;
const PX_TO_WORLD_Y = WORLD_HEIGHT / REFERENCE_HEIGHT;

const toWorld = (x: number, y: number, z = 0): Vec3 => [
  (x - REFERENCE_WIDTH / 2) * PX_TO_WORLD_X,
  (REFERENCE_HEIGHT / 2 - y) * PX_TO_WORLD_Y,
  z,
];

const rotationAtFrame = (frame: number, spec: MotionSpec): number => {
  const cycleLength = spec.segments.reduce((sum, segment) => sum + segment.duration, 0);
  const cycleAngle = spec.segments.reduce(
    (sum, segment) => sum + (segment.kind === "burst" ? segment.angle ?? 0 : 0),
    0,
  );
  const timeline = Math.max(0, frame + spec.offset);
  const cycle = Math.floor(timeline / cycleLength);
  let remaining = timeline % cycleLength;
  let angle = cycle * cycleAngle * spec.direction;

  for (const segment of spec.segments) {
    if (remaining >= segment.duration) {
      if (segment.kind === "burst") {
        angle += (segment.angle ?? 0) * spec.direction;
      }
      remaining -= segment.duration;
      continue;
    }

    if (segment.kind === "hold") {
      return angle;
    }

    const progress = remaining / segment.duration;
    const eased = Easing.inOut(Easing.quad)(progress);
    return angle + (segment.angle ?? 0) * eased * spec.direction;
  }

  return angle;
};

const motion = (
  direction: 1 | -1,
  offset: number,
  bursts: readonly [number, number][],
): MotionSpec => ({
  direction,
  offset,
  segments: bursts.flatMap(([duration, angle], index) => [
    {kind: "burst", duration, angle},
    {kind: "hold", duration: [4, 3, 5, 2, 6][index % 5]},
  ]),
});

