const AnimatedObject: React.FC<{
  readonly position: Vec3;
  readonly motionSpec: MotionSpec;
  readonly children: React.ReactNode;
  readonly scale?: number;
  readonly baseRotation?: Vec3;
}> = ({position, motionSpec, children, scale = 1, baseRotation = [0, 0, 0]}) => {
  const frame = useCurrentFrame();
  const spin = rotationAtFrame(frame, motionSpec);
  return (
    <group position={position} scale={scale} rotation={[baseRotation[0], baseRotation[1] + spin, baseRotation[2]]}>
      {children}
    </group>
  );
};

