export const AbstractSculptureMotion: React.FC = () => {
  const frame = useCurrentFrame();
  const {width, height} = useVideoConfig();
  const referenceOpacity = interpolate(frame, [0, 1], [1, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const sceneOpacity = 0;

  return (
    <AbsoluteFill
      style={{
        background: "linear-gradient(100deg, #f8e7d9 0%, #f4e1d4 46%, #d2baaa 100%)",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          background:
            "linear-gradient(to bottom, transparent 0%, transparent 82%, rgba(188,154,137,0.17) 100%), radial-gradient(ellipse at 53% 78%, rgba(167,128,111,0.12) 0%, transparent 34%)",
        }}
      />
      <div style={{position: "absolute", inset: 0, opacity: sceneOpacity}}>
        <ThreeCanvas
          width={width}
          height={height}
          orthographic
          shadows
          dpr={1}
          camera={{position: [0, 0, 12], zoom: 76, near: 0.1, far: 40}}
          gl={{
            antialias: true,
            alpha: true,
            toneMapping: THREE.ACESFilmicToneMapping,
            toneMappingExposure: 1.05,
            outputColorSpace: THREE.SRGBColorSpace,
          }}
          onCreated={({camera, gl}) => {
            camera.lookAt(0, 0, 0);
            camera.updateProjectionMatrix();
            gl.setClearColor(0x000000, 0);
          }}
        >
          <SculptureScene />
        </ThreeCanvas>
      </div>
      <Img
        src={staticFile("abstract-sculpture-reference.png")}
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
          objectFit: "fill",
          opacity: referenceOpacity,
          display: "block",
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};
