import React from 'react';
import {ShotState} from '../animation/shotController';
import {CinematicCamera} from './CinematicCamera';
import {StudioLighting} from './StudioLighting';
import {ChargingCase, Earbud} from '../Product';

interface PersistentStudioSceneProps {
  shot: ShotState;
}

export const PersistentStudioScene: React.FC<PersistentStudioSceneProps> = ({shot}) => {
  return (
    <>
      {/* Frame-driven cinematic camera */}
      <CinematicCamera
        position={shot.camera.position}
        target={shot.camera.target}
        fov={shot.camera.fov}
      />

      {/* Frame-driven studio lighting & floor reflection */}
      <StudioLighting
        preset={shot.lighting.preset}
        highlightSweep={shot.lighting.highlightSweep}
        showFloor={shot.lighting.showFloor}
      />

      {/* Charging Case (when active in shot) */}
      {shot.caseProps.visible && (
        <group
          position={shot.caseProps.position}
          rotation={shot.caseProps.rotation}
          scale={shot.caseProps.scale}
        >
          <ChargingCase opening={shot.caseProps.opening} />

          {/* Earbuds nested inside case coordinate system */}
          {shot.leftEarbudProps.visible && shot.leftEarbudProps.parent === 'case' && (
            <group
              position={shot.leftEarbudProps.position}
              rotation={shot.leftEarbudProps.rotation}
              scale={shot.leftEarbudProps.scale}
            >
              <Earbud side={-1} />
            </group>
          )}

          {shot.rightEarbudProps.visible && shot.rightEarbudProps.parent === 'case' && (
            <group
              position={shot.rightEarbudProps.position}
              rotation={shot.rightEarbudProps.rotation}
              scale={shot.rightEarbudProps.scale}
            >
              <Earbud side={1} />
            </group>
          )}
        </group>
      )}

      {/* Floating Earbuds in World space (e.g. Hero shot 06) */}
      {shot.leftEarbudProps.visible && shot.leftEarbudProps.parent === 'world' && (
        <group
          position={shot.leftEarbudProps.position}
          rotation={shot.leftEarbudProps.rotation}
          scale={shot.leftEarbudProps.scale}
        >
          <Earbud side={-1} />
        </group>
      )}

      {shot.rightEarbudProps.visible && shot.rightEarbudProps.parent === 'world' && (
        <group
          position={shot.rightEarbudProps.position}
          rotation={shot.rightEarbudProps.rotation}
          scale={shot.rightEarbudProps.scale}
        >
          <Earbud side={1} />
        </group>
      )}

      {/* Extreme Macro isolated earbud (e.g. Shot 05A & 05B) */}
      {shot.macroEarbudProps?.visible && (
        <group
          position={shot.macroEarbudProps.position}
          rotation={shot.macroEarbudProps.rotation}
          scale={shot.macroEarbudProps.scale}
        >
          {shot.macroEarbudProps.innerGroupPosition ? (
            <group position={shot.macroEarbudProps.innerGroupPosition}>
              <Earbud side={shot.macroEarbudProps.side} />
            </group>
          ) : (
            <Earbud side={shot.macroEarbudProps.side} />
          )}
        </group>
      )}
    </>
  );
};
