import { useCurrentFrame } from "remotion";

export const Lighting: React.FC = () => {
  const frame = useCurrentFrame();
  const daylight = 3.1 + Math.sin(frame / 70) * 0.035;

  return (
    <>
      <ambientLight intensity={0.62} color="#d7d8d5" />
      <hemisphereLight args={["#e8edf1", "#69615b", 0.48]} />
      <directionalLight
        position={[-3.2, 4.1, 1.2]}
        intensity={daylight}
        color="#ffe6c5"
        castShadow
        shadow-mapSize-width={2048}
        shadow-mapSize-height={2048}
        shadow-camera-near={0.1}
        shadow-camera-far={12}
        shadow-camera-left={-3}
        shadow-camera-right={3}
        shadow-camera-top={3}
        shadow-camera-bottom={-3}
        shadow-bias={-0.00025}
        shadow-normalBias={0.025}
        shadow-radius={4}
      />
      <directionalLight position={[1.8, 2.2, -2.5]} intensity={0.38} color="#c9d2dc" />
      <directionalLight position={[2.1, 2.7, -1.1]} intensity={0.72} color="#f5dfc4" />
    </>
  );
};
