import * as THREE from 'three';

export const makeCaseProfile = () => {
  const profile = [
    new THREE.Vector2(2.04, -0.29),
    new THREE.Vector2(2.18, -0.25),
    new THREE.Vector2(2.27, -0.12),
    new THREE.Vector2(2.30, 0.0),
    new THREE.Vector2(2.28, 0.12),
    new THREE.Vector2(2.20, 0.24),
    new THREE.Vector2(2.08, 0.29),
  ];
  const geometry = new THREE.LatheGeometry(profile, 96);
  geometry.rotateX(Math.PI / 2);
  geometry.computeVertexNormals();
  return geometry;
};

