import {useMemo} from 'react';
import * as THREE from 'three';
import {WatchDisplay} from './WatchDisplay';
import {WatchBracelet} from './WatchBracelet';
import {WatchCrown, WatchSideButton} from './WatchCrown';
import {WatchRearAssembly} from './WatchInternals';
import {ExplodedAssembly} from './ExplodedAssembly';
import {makeCaseProfile, makeGlassDome, makeRearProfile, makeRoundedRect, makeWatchFaceRing} from '../geometry/watchGeometry';
import {watchMaterials as M} from '../materials/watchMaterials';
import type {ChronosView} from '../config/productDimensions';

type PartProps = {name: string; assembled: [number, number, number]; direction: [number, number, number]; children: React.ReactNode};
const Part = ({name, assembled, direction, children}: PartProps) => (
  <group name={name} position={assembled} userData={{assembledPosition: assembled, disassemblyDirection: direction}}>{children}</group>
);

const lugGeometry = makeRoundedRect(0.42, 0.50, 0.42, 0.09);

const CaseDetails = () => (
  <group name="machined-case-details">
    <mesh name="upper-housing-seam" geometry={new THREE.TorusGeometry(2.22, 0.038, 8, 96)} position={[0, 0, 0.235]} material={M.titaniumEdge} />
    <mesh name="lower-housing-seam" geometry={new THREE.TorusGeometry(2.20, 0.032, 8, 96)} position={[0, 0, -0.22]} material={M.brushedMetal} />
    {[[-0.78, 2.12], [0.78, 2.12], [-0.78, -2.12], [0.78, -2.12]].map(([x, y], i) => (
      <group key={i} name="case-bracelet-lug" position={[x, y, 0]}>
        <mesh geometry={lugGeometry} material={M.titaniumEdge} />
        <mesh position={[0, 0, 0.22]} material={M.blackRubber}>
          <boxGeometry args={[0.19, 0.22, 0.025]} />
        </mesh>
      </group>
    ))}
    {[2.16, -2.16].map((y) => <mesh key={y} name="lug-hinge-pin" position={[0, y, 0.22]} rotation={[0, 0, Math.PI / 2]} material={M.screw}>
      <cylinderGeometry args={[0.08, 0.08, 1.28, 24]} />
    </mesh>)}
  </group>
);

export const ChronosWatch = ({view = 'front'}: {view?: ChronosView}) => {
  const caseGeometry = useMemo(makeCaseProfile, []);
  const rearGeometry = useMemo(makeRearProfile, []);
  const glassGeometry = useMemo(makeGlassDome, []);
  const bezelRing = useMemo(() => makeWatchFaceRing(1.93, 2.17, 0.31), []);
  const upperBezel = useMemo(() => makeWatchFaceRing(2.00, 2.21, 0.34), []);
  const back = view === 'back';
  if (view === 'exploded') return <ExplodedAssembly />;
  return (
    <group name="CHRONOS-X-watch" rotation={back ? [0, Math.PI, 0] : [0, 0, 0]}>
      <Part name="08-internal-housing" assembled={[0, 0, 0]} direction={[0, 0, -1]}>
        <mesh geometry={caseGeometry} material={M.titanium} />
        <mesh geometry={rearGeometry} position={[0, 0, -0.06]} material={M.titaniumEdge} />
        <mesh position={[0, 0, 0.245]} material={M.blackRubber}>
          <circleGeometry args={[2.12, 96]} />
        </mesh>
      </Part>
      <CaseDetails />
      {!back && <>
        <Part name="05-internal-structural-ring" assembled={[0, 0, 0.42]} direction={[0, 0, 1]}>
          <mesh geometry={makeWatchFaceRing(1.99, 2.22, 0)} material={M.titaniumEdge} />
        </Part>
        <Part name="02-upper-bezel" assembled={[0, 0, 0.04]} direction={[0, 0, 1]}>
          <mesh geometry={upperBezel} material={M.bezelDark} />
          <mesh geometry={bezelRing} material={M.brushedMetal} />
          <mesh geometry={makeWatchFaceRing(2.02, 2.07, 0.03)} material={M.titaniumEdge} />
        </Part>
        <Part name="03-display-panel" assembled={[0, 0, 0.09]} direction={[0, 0, 1]}>
          <WatchDisplay />
        </Part>
        <Part name="01-protective-glass" assembled={[0, 0, 0.15]} direction={[0, 0, 1]}>
          <mesh geometry={glassGeometry} material={M.glass} />
          <mesh material={M.glass} position={[0, 0, 0.05]}>
            <torusGeometry args={[1.975, 0.022, 8, 96]} />
          </mesh>
        </Part>
        <Part name="04-display-mounting-frame" assembled={[0, 0, 0.02]} direction={[0, 0, 1]}>
          <mesh geometry={makeWatchFaceRing(1.91, 1.97, 0.02)} material={M.blackRubber} />
        </Part>
      </>}
      <Part name="10-rear-cover" assembled={[0, 0, -0.05]} direction={[0, 0, -1]}>
        {back && <WatchRearAssembly />}
      </Part>
      <WatchCrown />
      <WatchSideButton />
      <WatchBracelet showBack={back} />
    </group>
  );
};
