import React, { useLayoutEffect, useRef } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from "remotion";

import * as THREE from "three";

export const HalloweenIdea: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const sceneRef = useRef<THREE.Scene | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);

  const dadRef = useRef<THREE.Group | null>(null);
  const bulbRef = useRef<THREE.Group | null>(null);
  const armRef = useRef<THREE.Group | null>(null);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  useLayoutEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color("#171d30");

    const camera = new THREE.PerspectiveCamera(
      40, 16 / 9, 0.1, 100
    );

    camera.position.set(0, 2.8, 9);
    camera.lookAt(0, 1.6, 0);

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
    });

    renderer.setSize(1280, 720, false);
    renderer.setPixelRatio(1);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;

    rendererRef.current = renderer;
    sceneRef.current = scene;
    cameraRef.current = camera;

    // LIGHTING

    scene.add(new THREE.AmbientLight(0xffffff, 1.8));

    const warmLight = new THREE.PointLight(0xffa34a, 100);
    warmLight.position.set(-3, 5, 4);
    scene.add(warmLight);

    const blueLight = new THREE.PointLight(0x426cff, 70);
    blueLight.position.set(4, 3, -3);
    scene.add(blueLight);

    // GARAGE FLOOR

    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(30, 30),
      new THREE.MeshStandardMaterial({ color: "#343747" })
    );

    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -0.05;
    scene.add(floor);

    // GARAGE BACK WALL

    const wall = new THREE.Mesh(
      new THREE.BoxGeometry(12, 7, 0.3),
      new THREE.MeshStandardMaterial({ color: "#555467" })
    );

    wall.position.set(0, 3, -2);
    scene.add(wall);

    // WORKBENCH

    const bench = new THREE.Mesh(
      new THREE.BoxGeometry(3.5, 0.25, 1.2),
      new THREE.MeshStandardMaterial({ color: "#75462b" })
    );

    bench.position.set(2.8, 1.2, -0.5);
    scene.add(bench);

    // DAD CHARACTER

    const dad = new THREE.Group();

    const skin = new THREE.MeshStandardMaterial({
      color: "#e6ad86",
      roughness: 0.8,
    });

    const shirt = new THREE.MeshStandardMaterial({
      color: "#e04b32",
    });

    const pants = new THREE.MeshStandardMaterial({
      color: "#303c59",
    });

    const hair = new THREE.MeshStandardMaterial({
      color: "#423027",
    });

    // BODY

    const torso = new THREE.Mesh(
      new THREE.CapsuleGeometry(0.48, 0.65, 8, 16),
      shirt
    );

    torso.position.y = 1.65;
    dad.add(torso);

    // HEAD

    const head = new THREE.Mesh(
      new THREE.SphereGeometry(0.43, 32, 32),
      skin
    );

    head.position.y = 2.65;
    dad.add(head);

    // HAIR

    const hairMesh = new THREE.Mesh(
      new THREE.SphereGeometry(0.44, 32, 24, 0, Math.PI * 2, 0, Math.PI * 0.42),
      hair
    );

    hairMesh.position.y = 2.77;
    dad.add(hairMesh);

    // EYES

    for (const x of [-0.15, 0.15]) {
      const eye = new THREE.Mesh(
        new THREE.SphereGeometry(0.055, 16, 16),
        new THREE.MeshBasicMaterial({ color: "#ffffff" })
      );

      eye.position.set(x, 2.69, 0.37);
      dad.add(eye);

      const pupil = new THREE.Mesh(
        new THREE.SphereGeometry(0.025, 12, 12),
        new THREE.MeshBasicMaterial({ color: "#171717" })
      );

      pupil.position.set(x, 2.69, 0.415);
      dad.add(pupil);
    }

    // NOSE

    const nose = new THREE.Mesh(
      new THREE.SphereGeometry(0.09, 16, 16),
      skin
    );

    nose.position.set(0, 2.55, 0.42);
    dad.add(nose);

    // LEGS

    for (const x of [-0.22, 0.22]) {
      const leg = new THREE.Mesh(
        new THREE.CapsuleGeometry(0.14, 0.55, 6, 12),
        pants
      );

      leg.position.set(x, 0.55, 0);
      dad.add(leg);
    }

    // ARMS

    const arm = new THREE.Group();

    const armMesh = new THREE.Mesh(
      new THREE.CapsuleGeometry(0.14, 0.6, 6, 12),
      shirt
    );

    armMesh.position.y = -0.35;
    arm.add(armMesh);

    arm.position.set(0.52, 2, 0);
    arm.rotation.z = -0.6;

    dad.add(arm);

    armRef.current = arm;

    dad.position.set(-1.5, 0, 0);
    scene.add(dad);

    dadRef.current = dad;

    // LIGHTBULB IDEA

    const bulb = new THREE.Group();

    const glass = new THREE.Mesh(
      new THREE.SphereGeometry(0.3, 32, 32),
      new THREE.MeshBasicMaterial({
        color: "#fff1a1",
      })
    );

    bulb.add(glass);

    const base = new THREE.Mesh(
      new THREE.CylinderGeometry(0.12, 0.16, 0.2, 16),
      new THREE.MeshStandardMaterial({
        color: "#a4a4a4",
        metalness: 0.8,
      })
    );

    base.position.y = -0.32;
    bulb.add(base);

    const glow = new THREE.PointLight(0xffd34e, 30, 5);
    bulb.add(glow);

    bulb.position.set(-0.2, 4, 0);

    scene.add(bulb);
    bulbRef.current = bulb;

    return () => {
      scene.clear();
      renderer.dispose();

      rendererRef.current = null;
      sceneRef.current = null;
      cameraRef.current = null;
      dadRef.current = null;
      bulbRef.current = null;
      armRef.current = null;
    };
  }, []);

  // FRAME-ACCURATE ANIMATION

  useLayoutEffect(() => {
    const renderer = rendererRef.current;
    const scene = sceneRef.current;
    const camera = cameraRef.current;

    if (!renderer || !scene || !camera) return;

    const time = frame / fps;

    // Dad gets excited

    if (dadRef.current) {
      const excitement = interpolate(
        frame,
        [60, 100, 140],
        [0, 1, 1],
        {
          easing: Easing.out(Easing.back(1.5)),
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }
      );

      dadRef.current.rotation.z = -0.08 * excitement;

      dadRef.current.position.y =
        Math.sin(time * 8) * 0.04 * excitement;
    }

    // Animated arm

    if (armRef.current) {
      const excitement = interpolate(
        frame,
        [65, 100, 145],
        [0, 1, 1],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      );

      armRef.current.rotation.z = -0.6 - excitement * 1.3;
    }

    // Lightbulb appears

    if (bulbRef.current) {
      const appearance = interpolate(
        frame,
        [70, 95],
        [0, 1],
        {
          easing: Easing.out(Easing.back(2)),
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        }
      );

      bulbRef.current.scale.setScalar(appearance);

      bulbRef.current.rotation.z = Math.sin(time * 3) * 0.1;
    }

    // Camera moves closer

    camera.position.z = 9 - Math.min(frame / 180, 1) * 1.2;
    camera.lookAt(0, 1.7, 0);

    renderer.render(scene, camera);
  }, [frame, fps]);

  const titleOpacity = interpolate(
    frame,
    [15, 40, 130, 170],
    [0, 1, 1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: "#171d30" }}>
      <canvas
        ref={canvasRef}
        style={{ width: "100%", height: "100%" }}
      />

      <div
        style={{
          position: "absolute",
          top: 45,
          width: "100%",
          textAlign: "center",
          fontSize: 46,
          fontWeight: 900,
          fontFamily: "Arial",
          color: "#ffcf76",
          opacity: titleOpacity,
          textShadow: "0 3px 15px #ff7b22",
        }}
      >
        DAD HAS AN IDEA!
      </div>
    </AbsoluteFill>
  );
};