import { useLayoutEffect } from "react";
import { interpolate, useCurrentFrame } from "remotion";
import { useThree } from "@react-three/fiber";
import * as THREE from "three";

type Shot = {
  from: number;
  to: number;
  fromPosition: [number, number, number];
  toPosition: [number, number, number];
  fromTarget: [number, number, number];
  toTarget: [number, number, number];
  fov: number;
};

const shots: Shot[] = [
  {
    from: 0,
    to: 89,
    fromPosition: [2.5, 1.05, 3.45],
    toPosition: [2.25, 0.96, 2.95],
    fromTarget: [0.1, 0.47, 0.05],
    toTarget: [0.1, 0.49, 0.05],
    fov: 34,
  },
  {
    from: 90,
    to: 149,
    fromPosition: [0.4, 1.01, 1.62],
    toPosition: [0.38, 0.99, 1.48],
    fromTarget: [0.43, 0.79, 0.54],
    toTarget: [0.43, 0.8, 0.55],
    fov: 27,
  },
  {
    from: 150,
    to: 239,
    fromPosition: [0.46, 0.89, 1.2],
    toPosition: [0.46, 0.88, 1.16],
    fromTarget: [0.46, 0.83, 0.55],
    toTarget: [0.46, 0.83, 0.55],
    fov: 21,
  },
  {
    from: 240,
    to: 299,
    fromPosition: [2.05, 0.9, 0.88],
    toPosition: [2.0, 0.9, 0.88],
    fromTarget: [0.2, 0.47, 0.03],
    toTarget: [0.2, 0.47, 0.03],
    fov: 36,
  },
];

const smooth = (start: number, end: number, frame: number) => {
  const t = interpolate(frame, [start, end], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return t * t * (3 - 2 * t);
};

export const CinematicCamera: React.FC = () => {
  const frame = useCurrentFrame();
  const { camera } = useThree();
  const shot = shots.find(({ from, to }) => frame >= from && frame <= to) ?? shots[3];
  const progress = smooth(shot.from, shot.to, frame);
  const subtleDrift = Math.sin(frame * 0.025) * 0.008;
  const positionX = THREE.MathUtils.lerp(shot.fromPosition[0], shot.toPosition[0], progress);
  const positionY = THREE.MathUtils.lerp(shot.fromPosition[1], shot.toPosition[1], progress);
  const positionZ = THREE.MathUtils.lerp(shot.fromPosition[2], shot.toPosition[2], progress);
  const targetX = THREE.MathUtils.lerp(shot.fromTarget[0], shot.toTarget[0], progress);
  const targetY = THREE.MathUtils.lerp(shot.fromTarget[1], shot.toTarget[1], progress);
  const targetZ = THREE.MathUtils.lerp(shot.fromTarget[2], shot.toTarget[2], progress);

  useLayoutEffect(() => {
    camera.position.set(positionX + subtleDrift, positionY, positionZ);
    camera.lookAt(targetX, targetY, targetZ);
    if (camera instanceof THREE.PerspectiveCamera) {
      camera.fov = shot.fov;
      camera.updateProjectionMatrix();
    }
    camera.updateMatrixWorld();
  }, [camera, positionX, positionY, positionZ, targetX, targetY, targetZ, subtleDrift, shot.fov]);

  return null;
};
