const roofSurfaceY = (
  x: number,
  z: number,
  width: number,
  depth: number,
  ridgeHeight: number,
  upturn: number,
  variant: RoofVariant,
) => {
  const nx = Math.min(1, Math.abs(x) / (width / 2));
  const nz = Math.min(1, Math.abs(z) / (depth / 2));
  const ridgeProfile = variant === "gable" ? 1.0 : 0.88;
  const centerSlope = ridgeHeight * ridgeProfile * (1 - Math.pow(nx, 1.34));
  const depthCrown = ridgeHeight * 0.12 * (1 - Math.pow(nz, 1.5));
  const eaveLift = upturn * Math.pow(nx, 3.2);
  const cornerLift = upturn * 0.42 * Math.pow(nz, 2.4) * (0.18 + 0.82 * nx);
  return centerSlope + depthCrown + eaveLift + cornerLift - ridgeHeight * 0.05 * Math.pow(nz, 1.8);
};

const createCurvedRoofGeometry = (
  width: number,
  depth: number,
  ridgeHeight: number,
  upturn: number,
  thickness: number,
  variant: RoofVariant,
) => {
  const xSegments = 24;
  const zSegments = 10;
  const vertices: number[] = [];
  const indices: number[] = [];
  const rowSize = xSegments + 1;

  for (let iz = 0; iz <= zSegments; iz += 1) {
    const z = -depth / 2 + (iz / zSegments) * depth;
    for (let ix = 0; ix <= xSegments; ix += 1) {
      const x = -width / 2 + (ix / xSegments) * width;
      vertices.push(x, roofSurfaceY(x, z, width, depth, ridgeHeight, upturn, variant), z);
    }
  }
  for (let iz = 0; iz <= zSegments; iz += 1) {
    const z = -depth / 2 + (iz / zSegments) * depth;
    for (let ix = 0; ix <= xSegments; ix += 1) {
      const x = -width / 2 + (ix / xSegments) * width;
      const top = roofSurfaceY(x, z, width, depth, ridgeHeight, upturn, variant);
      vertices.push(x, top - thickness, z);
    }
  }

  const bottomStart = rowSize * (zSegments + 1);
  for (let iz = 0; iz < zSegments; iz += 1) {
    for (let ix = 0; ix < xSegments; ix += 1) {
      const a = iz * rowSize + ix;
      const b = a + 1;
      const c = (iz + 1) * rowSize + ix;
      const d = c + 1;
      indices.push(a, d, b, a, c, d);
      indices.push(bottomStart + a, bottomStart + b, bottomStart + d, bottomStart + a, bottomStart + d, bottomStart + c);
    }
  }

  const addSide = (topA: number, topB: number, bottomA: number, bottomB: number) => {
    indices.push(topA, bottomA, bottomB, topA, bottomB, topB);
  };
  for (let ix = 0; ix < xSegments; ix += 1) {
    addSide(ix, ix + 1, bottomStart + ix, bottomStart + ix + 1);
    const back = zSegments * rowSize + ix;
    addSide(back + 1, back, bottomStart + back + 1, bottomStart + back);
  }
  for (let iz = 0; iz < zSegments; iz += 1) {
    const front = iz * rowSize;
    addSide(front + rowSize, front, bottomStart + front + rowSize, bottomStart + front);
    const right = iz * rowSize + xSegments;
    addSide(right, right + rowSize, bottomStart + right, bottomStart + right + rowSize);
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
};

