const createArchBandGeometry = (innerRadius: number, outerRadius: number, depth: number, segments = 24) => {
  const vertices: number[] = [];
  const indices: number[] = [];
  const add = (x: number, y: number, z: number) => {
    vertices.push(x, y, z);
    return vertices.length / 3 - 1;
  };
  for (let index = 0; index <= segments; index += 1) {
    const theta = (index / segments) * Math.PI;
    const sin = Math.sin(theta);
    const cos = Math.cos(theta);
    const innerFront = add(innerRadius * cos, 0.24 + innerRadius * sin, depth / 2);
    const outerFront = add(outerRadius * cos, 0.24 + outerRadius * sin, depth / 2);
    const innerBack = add(innerRadius * cos, 0.24 + innerRadius * sin, -depth / 2);
    const outerBack = add(outerRadius * cos, 0.24 + outerRadius * sin, -depth / 2);
    if (index > 0) {
      const previous = (index - 1) * 4;
      const current = index * 4;
      indices.push(previous + 1, current + 1, current, previous + 1, current, previous);
      indices.push(previous + 2, current + 2, current + 3, previous + 2, current + 3, previous + 3);
      indices.push(previous + 1, previous + 3, current + 3, previous + 1, current + 3, current + 1);
      indices.push(previous, current, current + 2, previous, current + 2, previous + 2);
    }
    if (index === 0) {
      indices.push(innerFront, outerFront, outerBack, innerFront, outerBack, innerBack);
    }
    if (index === segments) {
      indices.push(innerFront, innerBack, outerBack, innerFront, outerBack, outerFront);
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.Float32BufferAttribute(vertices, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
};

