const createPalePolyhedron = (config: AssetConfig) => (
  <mesh castShadow receiveShadow position={config.position} rotation={config.rotation} scale={config.scale}>
    <icosahedronGeometry args={[0.45, 0]} />
    {materialFor(config, true)}
  </mesh>
);

const factories: Record<Exclude<ReconstructionAsset, "all">, (config: AssetConfig) => React.ReactNode> = {
  "green-triangle": createGreenTriangle,
  "teal-cylinder": createTealCylinder,
  "lime-semicircle": createLimeSemicircle,
  "teal-polyhedron": createTealPolyhedron,
  "green-star": createGreenFourPointStar,
  "ivory-triangle": createIvoryTriangle,
  "pale-polyhedron": createPalePolyhedron,
};

const assetNames = Object.keys(assetConfigs) as Array<Exclude<ReconstructionAsset, "all">>;

const SharedLighting: React.FC = () => (
  <>
    <ambientLight intensity={0.65} color="#fff2e9" />
    <hemisphereLight intensity={0.35} color="#fff7f1" groundColor="#c4a99a" />
    <directionalLight
      position={[-5, 5, 8]}
      intensity={1.9}
      color="#fff4ed"
      castShadow
      shadow-mapSize={[2048, 2048]}
      shadow-camera-left={-16}
      shadow-camera-right={16}
      shadow-camera-top={5}
      shadow-camera-bottom={-5}
    />
    <directionalLight position={[4, 1, 5]} intensity={0.4} color="#f7d7cd" />
  </>
);

const StaticScene: React.FC<{readonly asset: ReconstructionAsset}> = ({asset}) => {
  const names = asset === "all" ? assetNames : [asset];
  return (
    <>
      <SharedLighting />
      <mesh position={[0, 0, -1.4]} receiveShadow>
        <planeGeometry args={[40, 12]} />
        <shadowMaterial transparent opacity={0.08} color="#a17f70" />
      </mesh>
      {names.map((name) => <React.Fragment key={name}>{factories[name](assetConfigs[name])}</React.Fragment>)}
    </>
  );
};

export const AbstractAssetReconstruction: React.FC<{readonly asset?: ReconstructionAsset}> = ({asset = "all"}) => {
  const {width, height} = useVideoConfig();
  return (
    <AbsoluteFill
      style={{
        background: "linear-gradient(100deg, #f8e7d9 0%, #f4e1d4 48%, #d1b8a8 100%)",
        overflow: "hidden",
      }}
    >
      <ThreeCanvas
        width={width}
        height={height}
        orthographic
        shadows
        dpr={1}
        camera={{position: [0, 0, 12], zoom: 78, near: 0.1, far: 40}}
        gl={{
          antialias: true,
          alpha: true,
          toneMapping: THREE.ACESFilmicToneMapping,
          toneMappingExposure: 1.04,
          outputColorSpace: THREE.SRGBColorSpace,
        }}
        onCreated={({camera, gl}) => {
          camera.lookAt(0, 0, 0);
          camera.updateProjectionMatrix();
          gl.setClearColor(0x000000, 0);
        }}
      >
        <StaticScene asset={asset} />
      </ThreeCanvas>
    </AbsoluteFill>
  );
};
