import React from "react";
import { ThreeCanvas } from "@remotion/three";
import { Audio } from "@remotion/media";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import * as THREE from "three";
import { CinematicCamera } from "../components/CinematicCamera";
import { DobermanModel } from "../components/DobermanModel";
import { DustParticles } from "../components/DustParticles";
import { Lighting } from "../components/Lighting";
import { ModernInterior } from "../components/ModernInterior";

type SceneProps = {
  narrationReady?: boolean;
};

const Title: React.FC = () => {
  const frame = useCurrentFrame();
  const opacity = interpolate(frame, [12, 28, 62, 82], [0, 0.86, 0.86, 0], {
    easing: Easing.inOut(Easing.ease),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        left: 90,
        bottom: 94,
        color: "#f4efe7",
        opacity,
        fontFamily: '"Iowan Old Style", "Palatino Linotype", Georgia, serif',
        fontSize: 26,
        fontWeight: 500,
        letterSpacing: 5.4,
        textShadow: "0 2px 18px rgba(16, 18, 20, 0.4)",
        pointerEvents: "none",
      }}
    >
      THE DOBERMAN
    </div>
  );
};

export const Scene01_Introduction: React.FC<SceneProps> = ({ narrationReady = false }) => {
  const { width, height } = useVideoConfig();
  const frame = useCurrentFrame();

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "#e99515",
        translate: "-225.8px 0px",
        borderRadius: 10
      }}
    >
      <ThreeCanvas
        width={width}
        height={height}
        dpr={1.25}
        shadows
        gl={{
          antialias: true,
          toneMapping: THREE.ACESFilmicToneMapping,
          toneMappingExposure: 1.02,
          outputColorSpace: THREE.SRGBColorSpace,
        }}
        camera={{ position: [0.55, 1.05, 3.45], fov: 34, near: 0.05, far: 45 }}
      >
        <color attach="background" args={["#b9b5af"]} />
        <fog attach="fog" args={["#b9b5af", 7, 18]} />
        <Lighting />
        <ModernInterior />
        <CinematicCamera />
        <DobermanModel />
        <DustParticles />
      </ThreeCanvas>
      <Title />
      {narrationReady && (
        <Audio
          name="Narration · Scene 01"
          src={staticFile("audio/narration/scene-01-introduction.mp3")}
          volume={interpolate(frame, [0, 8, 278, 299], [0, 1, 1, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          })}
        />
      )}
    </AbsoluteFill>
  );
};
