import {useMemo} from 'react';
import * as THREE from 'three';
import {watchMaterials as M} from '../materials/watchMaterials';

const makeDisplayTexture = () => {
  const canvas = document.createElement('canvas');
  canvas.width = 768;
  canvas.height = 768;
  const ctx = canvas.getContext('2d');
  if (!ctx) return new THREE.CanvasTexture(canvas);
  const center = 384;
  const gradient = ctx.createRadialGradient(center, center, 40, center, center, 384);
  gradient.addColorStop(0, '#06182f');
  gradient.addColorStop(0.72, '#020817');
  gradient.addColorStop(1, '#00030a');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 768, 768);

  ctx.strokeStyle = '#0b9bff';
  ctx.lineWidth = 11;
  ctx.beginPath();
  ctx.arc(center, center, 332, Math.PI * 0.13, Math.PI * 1.85);
  ctx.stroke();
  ctx.strokeStyle = '#2b67be';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(center, center, 305, Math.PI * 1.06, Math.PI * 1.94);
  ctx.stroke();

  ctx.fillStyle = '#e3f4ff';
  ctx.font = '112px Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('10:09', center, 370);
  ctx.fillStyle = '#73c9ff';
  ctx.font = '25px Arial, sans-serif';
  ctx.letterSpacing = '5px';
  ctx.fillText('WED 24 NOV', center, 420);
  ctx.fillStyle = '#9cdcff';
  ctx.font = '21px Arial, sans-serif';
  ctx.fillText('72 BPM        BATTERY 86%', center, 497);

  ctx.strokeStyle = '#2e77c9';
  ctx.lineWidth = 3;
  for (let i = 0; i < 12; i += 1) {
    const angle = (i / 12) * Math.PI * 2 - Math.PI / 2;
    const r1 = i % 3 === 0 ? 275 : 286;
    const r2 = 297;
    ctx.beginPath();
    ctx.moveTo(center + Math.cos(angle) * r1, center + Math.sin(angle) * r1);
    ctx.lineTo(center + Math.cos(angle) * r2, center + Math.sin(angle) * r2);
    ctx.stroke();
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 2;
  return texture;
};

export const WatchDisplay = () => {
  const texture = useMemo(makeDisplayTexture, []);
  const displayMaterial = useMemo(() => M.display.clone(), []);
  displayMaterial.color.set('#ffffff');
  displayMaterial.emissive.set('#9bdcff');
  displayMaterial.map = texture;
  displayMaterial.emissiveMap = texture;
  displayMaterial.emissiveIntensity = 1.55;
  texture.rotation = Math.PI / 2;
  texture.center.set(0.5, 0.5);
  texture.needsUpdate = true;
  displayMaterial.needsUpdate = true;
  return (
    <group name="03-display-panel">
      <mesh position={[0, 0, 0.32]} rotation={[Math.PI / 2, 0, 0]} material={displayMaterial}>
        <cylinderGeometry args={[1.93, 1.93, 0.065, 96]} />
        <primitive object={displayMaterial} attach="material" />
      </mesh>
      <mesh position={[0, 0, 0.358]} material={M.blueGlow}>
        <ringGeometry args={[1.98, 2.0, 96]} />
      </mesh>
    </group>
  );
};
